-- Assan Zameen: merged blog articles
-- 22 unique articles, English and Urdu. Generated 2026-11-01.
--
-- Import into the site's existing database (phpMyAdmin > Import, or mysql client).
-- Safe to run more than once. It does not drop any table or delete any article.
-- If posts is missing it is created and the original ids 1 to 12 are restored, so reviews stay linked.
-- Existing articles keep their id, views, likes, author and reviews.

SET NAMES utf8mb4;
SET time_zone = '+00:00';

-- If the posts table is missing, create it. If it already exists, this does nothing.
CREATE TABLE IF NOT EXISTS `posts` (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) UNSIGNED NOT NULL,
  `title` varchar(255) NOT NULL,
  `title_ur` varchar(255) DEFAULT NULL,
  `slug` varchar(255) NOT NULL,
  `category` varchar(255) NOT NULL DEFAULT 'Real Estate News',
  `featured_image` varchar(255) DEFAULT NULL,
  `summary` text DEFAULT NULL,
  `summary_ur` text DEFAULT NULL,
  `content` longtext NOT NULL,
  `content_ur` longtext DEFAULT NULL,
  `tags` varchar(255) DEFAULT NULL,
  `read_time` int(11) NOT NULL DEFAULT 3,
  `views_count` bigint(20) UNSIGNED NOT NULL DEFAULT 0,
  `likes_count` bigint(20) UNSIGNED NOT NULL DEFAULT 0,
  `is_featured` tinyint(1) NOT NULL DEFAULT 0,
  `status` enum('published','draft') NOT NULL DEFAULT 'published',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `posts_slug_unique` (`slug`),
  KEY `posts_user_id_foreign` (`user_id`),
  CONSTRAINT `posts_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Same columns as migration 2026_11_01_120000_add_urdu_fields_to_posts_table
ALTER TABLE `posts`
  ADD COLUMN IF NOT EXISTS `title_ur` varchar(255) DEFAULT NULL AFTER `title`,
  ADD COLUMN IF NOT EXISTS `summary_ur` text DEFAULT NULL AFTER `summary`,
  ADD COLUMN IF NOT EXISTS `content_ur` longtext DEFAULT NULL AFTER `content`;

-- Mark the migration as done so `php artisan migrate` does not try to add the columns again
INSERT INTO `migrations` (`migration`, `batch`)
SELECT '2026_11_01_120000_add_urdu_fields_to_posts_table', COALESCE((SELECT MAX(m.`batch`) FROM `migrations` m), 0) + 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `migrations` x WHERE x.`migration` = '2026_11_01_120000_add_urdu_fields_to_posts_table');

START TRANSACTION;

-- 1. punjab-plot-registry-tax-fee-schedule-guide
INSERT INTO `posts` (`id`, `user_id`, `title`, `title_ur`, `slug`, `category`, `featured_image`, `summary`, `summary_ur`, `content`, `content_ur`, `tags`, `read_time`, `views_count`, `likes_count`, `is_featured`, `status`, `created_at`, `updated_at`) VALUES (
  1,
  COALESCE((SELECT u.`id` FROM `users` u WHERE u.`role` = 'admin' ORDER BY u.`id` LIMIT 1), (SELECT MIN(u2.`id`) FROM `users` u2)),
  'Plot Registry Costs in Punjab: Stamp Duty, TMA, FBR Tax and PLRA Charges',
  'پنجاب میں پلاٹ رجسٹری کا نیا سرکاری شیڈول: فائلر اور نان فائلر کے تمام اخراجات کی تفصیل',
  'punjab-plot-registry-tax-fee-schedule-guide',
  'Taxes & Laws',
  'blog_images/1792515638_6ad79e3638263.jpg',
  'The main government charges on a property registry in Punjab: stamp duty, local council fee, FBR 236-K and 236-C tax, PLRA and registration fees.',
  'پنجاب میں اراضی، مکان یا پلاٹ کی رجسٹری اور انتقال کرواتے وقت کتنے سرکاری چالان ادا کرنے پڑتے ہیں؟ اسٹامپ ڈیوٹی، ٹی ایم اے ٹیکس، ایف بی آر سیکشن 236-C/K اور پی ایل آر اے فیسوں کا مستند سرکاری حساب۔',
  '<p>Many buyers arrive at the registry office without knowing what they will have to pay. Here are the main charges to plan for. Rates change, and some published figures differ, so treat this as a checklist and let the official challan give you the final amount.</p>\n<h2>1. Stamp duty</h2>\n<p>Stamp duty is paid through an e-Stamp challan. PLRA says it is calculated on the declared value or the DC valuation, whichever is higher. The rate depends on current Punjab law, so see the amount the <a href=\"https://www.assanzameen.com/blog/e-stamp-challan-32a-kaise-banayein-punjab-guide\">e-Stamp system</a> calculates.</p>\n<h2>2. Local council fee</h2>\n<p>A local government charge may apply, depending on the area. Ask the registry office or Arazi Record Centre what applies to your property.</p>\n<h2>3. FBR tax on the buyer (section 236-K)</h2>\n<p>Advance tax on the buyer depends on filer status and the property value. Non-filers pay a much higher rate. Check your <a href=\"https://e.fbr.gov.pk/atl/\" rel=\"noopener\" target=\"_blank\">status on the ATL</a>.</p>\n<h2>4. FBR tax on the seller (section 236-C)</h2>\n<p>The seller also pays tax based on filer status, and non-filers pay much more. Agree early who pays what.</p>\n<h2>5. PLRA and registration charges</h2>\n<ul>\n<li><strong>PLRA service charge:</strong> the FY 2025-26 schedule lists 0.1% of land value on sale and purchase through e-Registration, subject to a minimum of Rs. 3,300.</li>\n<li><strong>Registration fee:</strong> paid along with stamp duty and CVT on Challan 32-A.</li>\n<li><strong>Mutation:</strong> check the current fee at the centre, and see our <a href=\"https://www.assanzameen.com/blog/bai-zubani-intiqal-ka-tareeqa-fee-punjab\">mutation guide</a>.</li>\n</ul>\n<h2>Plan your budget</h2>\n<ol>\n<li>Check the <a href=\"https://www.assanzameen.com/blog/dc-valuation-kaise-check-karein-punjab\">DC rate</a> for your area.</li>\n<li>Estimate the total with our <a href=\"https://www.assanzameen.com/tools/registry-tax-calculator\">Registry & Tax Calculator</a>.</li>\n<li>Generate the official challan for the exact amount before you pay.</li>\n</ol>\n<h2>More help</h2>\n<p>Open our <a href=\"https://www.assanzameen.com/tools/government-links\">Government Links Guide</a> to see all the official portals in one place. To contact PLRA or make a complaint, call <strong>(042) 111-22-22-77</strong> (Monday to Saturday, 8:00 AM to 5:00 PM).</p>\n<blockquote>This article was written on 1 November 2026 from information on the PLRA website. Assan Zameen is not a government body. Fees and procedures can change, so confirm with the relevant office before paying. This is not legal advice.</blockquote>',
  '<p>&lt;h2&gt;پنجاب میں پلاٹ رجسٹری و انتقال: سرکاری فیس شیڈول کا مکمل جائزہ&lt;/h2&gt;</p><p><br></p><p>&lt;p&gt;پاکستان میں ریئل اسٹیٹ کی خرید و فروخت کا سب سے اہم مرحلہ رجسٹری اور انتقال کا ہوتا ہے۔ اکثر خریدار اور سرمایہ کار کچہری جانے سے پہلے سرکاری فیسوں اور چالان کی درست رقوم سے ناواقف ہوتے ہیں، جس کی وجہ سے ڈیلرز یا ایجینٹس کے غیر ضروری چکر لگانے پڑتے ہیں۔ محکمہ ریونیو حکومتِ پنجاب اور فیڈرل بورڈ آف ریونیو (FBR) کے جاری کردہ تازہ ترین شیڈول کے مطابق سرکاری واجبات کی مکمل تفصیل درج ذیل ہے۔&lt;/p&gt;</p><p><br></p><p>&lt;h3&gt;1. اسٹامپ ڈیوٹی (Stamp Duty)&lt;/h3&gt;</p><p>&lt;p&gt;پنجاب اسٹامپ ترمیمی ایکٹ کے تحت اربن (شہری/رہائشی) اور رورل (زرعی/دیہی) اراضی کی منتقلی پر یکساں &lt;strong&gt;1 فیصد (1%)&lt;/strong&gt; اسٹامپ ڈیوٹی نافذ ہے۔ لیکن اگر آپ ایسی رہائشی یا کمرشل عمارت خرید رہے ہیں جس کا مجاز ادارے سے باقاعدہ نقشہ پاس نہ ہو، تو رقبے کی قیمت پر اسٹامپ ڈیوٹی &lt;strong&gt;2 فیصد&lt;/strong&gt; لاگو ہوتی ہے۔&lt;/p&gt;</p><p><br></p><p>&lt;h3&gt;2. ٹی ایم اے ٹیکس (TMA / TIP Tax)&lt;/h3&gt;</p><p>&lt;p&gt;اگر خریدی جانے والی جائیداد کسی ٹاؤن کمیٹی، میونسپل کمیٹی یا کارپوریشن کے دائرہ اختیار میں واقع ہو، تو لوکل گورنمنٹ ایکٹ کے تحت &lt;strong&gt;1 فیصد (1%)&lt;/strong&gt; لوکل کونسل فیس کا ای-چالان لازمی جمع کروانا ہوتا ہے۔&lt;/p&gt;</p><p><br></p><p>&lt;h3&gt;3. خریدار کا ایڈوانس انکم ٹیکس (FBR Section 236-K)&lt;/h3&gt;</p><p>&lt;p&gt;فیڈرل بورڈ آف ریونیو (FBR) کے ضوابط کے تحت خریدار کے فائلر اور نان فائلر اسٹیٹس کے مطابق ٹیکس سلیبز مقرر ہیں:&lt;/p&gt;</p><p>&lt;ul&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;&lt;strong&gt;ایکٹو فائلر (Active Filer):&lt;/strong&gt; خریدار اگر ایف بی آر کی ایکٹو ٹیکس پیئر لسٹ میں شامل ہے تو اسے کل سرکاری مالیت پر صرف &lt;strong&gt;1.25 فیصد&lt;/strong&gt; ٹیکس ادا کرنا ہوتا ہے۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;&lt;strong&gt;نان فائلر (Non-Filer):&lt;/strong&gt; نان فائلر خریدار کے لیے 5 کروڑ روپے تک کی مالیت پر &lt;strong&gt;10.5 فیصد&lt;/strong&gt;، 5 کروڑ سے 10 کروڑ روپے پر &lt;strong&gt;14.5 فیصد&lt;/strong&gt;، اور 10 کروڑ روپے سے زائد کی مالیت پر &lt;strong&gt;18.5 فیصد&lt;/strong&gt; جرمانہ ٹیکس چالان بھرنا پڑتا ہے۔&lt;/li&gt;</p><p>&lt;/ul&gt;</p><p><br></p><p>&lt;h3&gt;4. فروخت کنندہ کا ٹیکس (FBR Section 236-C)&lt;/h3&gt;</p><p>&lt;p&gt;پراپرٹی بیچنے والے مالک کے ذمے بھی ایڈوانس انکم ٹیکس عائد ہوتا ہے:&lt;/p&gt;</p><p>&lt;ul&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;فائلر فروخت کنندہ کے لیے یہ شرح &lt;strong&gt;2.75 فیصد&lt;/strong&gt; ہے۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;نان فائلر فروخت کنندہ کے لیے یہ شرح &lt;strong&gt;11.5 فیصد&lt;/strong&gt; ہے۔&lt;/li&gt;</p><p>&lt;/ul&gt;</p><p><br></p><p>&lt;h3&gt;5. پی ایل آر اے اور رجسٹریشن چارجز (PLRA &amp; Registration Fees)&lt;/h3&gt;</p><p>&lt;ul&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;&lt;strong&gt;پی ایل آر اے فیس (PLRA Charges):&lt;/strong&gt; 30 لاکھ روپے تک کی مالیت پر یکمشت &lt;strong&gt;3,300 روپے&lt;/strong&gt; اور 30 لاکھ روپے سے زائد کی جائیداد پر &lt;strong&gt;0.1 فیصد&lt;/strong&gt; سروس چارجز وصول کیے جاتے ہیں۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;&lt;strong&gt;سب رجسٹرار فیس (Registration Charges):&lt;/strong&gt; 5 لاکھ روپے تک مالیت پر &lt;strong&gt;500 روپے&lt;/strong&gt; اور 5 لاکھ سے زائد مالیت پر &lt;strong&gt;1,000 روپے&lt;/strong&gt; فیس لاگو ہوتی ہے۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;&lt;strong&gt;دیگر سرکاری چارجز:&lt;/strong&gt; موازنہ/مقابلہ فیس &lt;strong&gt;100 روپے&lt;/strong&gt; جبکہ انتقال فیس وغیرہ &lt;strong&gt;600 روپے&lt;/strong&gt; وصول کی جاتی ہے۔&lt;/li&gt;</p><p>&lt;/ul&gt;</p><p><br></p><p>&lt;p&gt;&lt;em&gt;مشورہ: سودا فائنل کرنے سے پہلے آسان زمین (AssanZameen) کے آن لائن ٹیکس کیلکولیٹر سے خریدار اور بیچنے والے کے الگ الگ اور مشترکہ چالان کی درست رقم فوری معلوم کر لیں۔&lt;/em&gt;&lt;/p&gt;</p>',
  'PLRA,estamp duty,fbr,236c,236k,filer,registry',
  '5',
  '28',
  '0',
  '0',
  'published',
  '2026-10-20 21:45:27',
  '2026-11-01 14:53:34'
)
ON DUPLICATE KEY UPDATE
  `title` = VALUES(`title`), `title_ur` = VALUES(`title_ur`), `summary` = VALUES(`summary`), `summary_ur` = VALUES(`summary_ur`), `content` = VALUES(`content`), `content_ur` = VALUES(`content_ur`),
  `featured_image` = COALESCE(`featured_image`, VALUES(`featured_image`));

-- 2. online-fard-malkiyat-punjab-arazi-record-center
INSERT INTO `posts` (`id`, `user_id`, `title`, `title_ur`, `slug`, `category`, `featured_image`, `summary`, `summary_ur`, `content`, `content_ur`, `tags`, `read_time`, `views_count`, `likes_count`, `is_featured`, `status`, `created_at`, `updated_at`) VALUES (
  2,
  COALESCE((SELECT u.`id` FROM `users` u WHERE u.`role` = 'admin' ORDER BY u.`id` LIMIT 1), (SELECT MIN(u2.`id`) FROM `users` u2)),
  'Online Fard in Punjab: Types of Fard and How to Apply on the PLRA Portal',
  'پنجاب میں آن لائن فردِ ملکیت حاصل کرنے کا طریقہ: اراضی ریکارڈ سنٹر جائے بغیر تصدیق',
  'online-fard-malkiyat-punjab-arazi-record-center',
  'Property Guides',
  'blog_images/1792517774_6ad7a68e00c00.jpg',
  'The types of fard in Punjab and how to apply online through PLRA: login, ownership details, fee payment, QR code verification and status tracking.',
  'پنجاب لینڈ ریکارڈز اتھارٹی (PLRA) کے ڈیجیٹل پورٹل سے پلاٹ یا زرعی زمین کی فرد برائے بیع، ریکارڈ یا ضمانت چند منٹوں میں آن لائن حاصل کرنے کا مکمل مرحلہ وار طریقہ کار۔',
  '<p>Checking a land record no longer has to mean a full day in a queue. PLRA has computerized records, and in many cases you can apply for a fard online.</p>\n<h2>Types of fard</h2>\n<ul>\n<li><strong>Information fard:</strong> for checking and verification only.</li>\n<li><strong>Sale fard:</strong> used for a registry and transfer of ownership. The buyer\'s name and CNIC are mandatory.</li>\n<li><strong>Surety (zamanat) fard:</strong> used in court matters. You may also get a sale fard if the court has not restricted the sale.</li>\n</ul>\n<h2>Applying online</h2>\n<ol>\n<li>Open the <a href=\"https://onlinefard.punjab-zameen.gov.pk/\" rel=\"noopener\" target=\"_blank\">PLRA online fard portal</a>, or use the Punjab Zameen mobile app.</li>\n<li>Log in and verify the ownership details.</li>\n<li>Pay the fee online.</li>\n<li>Get your fard, and note its fard ID.</li>\n</ol>\n<p>Your record must be computerized for this to work. If it is not, contact the area patwari.</p>\n<h2>What does it cost?</h2>\n<p>According to PLRA, the fee is normally Rs. 50 per khatooni, up to Rs. 150 per khewat, plus PLRA service charges. The system shows the final amount, which depends on your record. The service charge for a copy of a record is set out in the <a href=\"https://www.punjab-zameen.gov.pk/guidanceAndRegulation\" rel=\"noopener\" target=\"_blank\">PLRA notifications</a>.</p>\n<h2>Verify every fard</h2>\n<p>Each fard has a QR code. Scan the seller\'s fard before buying, to protect yourself from fake papers. PLRA also advises getting the latest fard before any transaction. You can check a request\'s status online with your fard ID.</p>\n<p>See our <a href=\"https://www.assanzameen.com/blog/fard-kaise-hasil-karein-punjab-online-arc-guide\">full fard guide</a> for documents, lost fards and fingerprint problems.</p>\n<h2>More help</h2>\n<p>Open our <a href=\"https://www.assanzameen.com/tools/government-links\">Government Links Guide</a> to see all the official portals in one place. To contact PLRA or make a complaint, call <strong>(042) 111-22-22-77</strong> (Monday to Saturday, 8:00 AM to 5:00 PM).</p>\n<blockquote>This article was written on 1 November 2026 from information on the PLRA website. Assan Zameen is not a government body. Fees and procedures can change, so confirm with the relevant office before paying. This is not legal advice.</blockquote>',
  '<p>&lt;h2&gt;آن لائن فردِ ملکیت کیسے نکالیں؟ پی ایل آر اے ڈیجیٹل سسٹم کی مکمل رہنمائی&lt;/h2&gt;</p><p><br></p><p>&lt;p&gt;وہ دور گزر چکا جب زمین کا ریکارڈ چیک کرنے یا فردِ ملکیت نکلوانے کے لیے پٹواریوں کے ڈیروں یا اراضی ریکارڈ سنٹرز کی لمبی قطاروں میں پورا دن ضائع کرنا پڑتا تھا۔ پنجاب لینڈ ریکارڈز اتھارٹی (PLRA) نے اراضی کے تمام ریکارڈز کو کمپیوٹرائزڈ کر کے عوام کے لیے گھر بیٹھے فرد کے حصول کا عمل انتہائی آسان بنا دیا ہے۔&lt;/p&gt;</p><p><br></p><p>&lt;h3&gt;فرد کی اقسام&lt;/h3&gt;</p><p>&lt;p&gt;آن لائن درخواست دینے سے پہلے یہ جاننا ضروری ہے کہ آپ کو کس مقصد کے لیے فرد درکار ہے:&lt;/p&gt;</p><p>&lt;ol&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;&lt;strong&gt;فرد برائے معلومات / ریکارڈ:&lt;/strong&gt; یہ صرف اپنی زمین کی ملکیت، رقبہ اور خسرہ نمبر چیک کرنے کے لیے حاصل کی جاتی ہے۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;&lt;strong&gt;فرد برائے بیع (Sale):&lt;/strong&gt; یہ جائیداد بیچنے اور باقاعدہ رجسٹری کروانے کے لیے جاری کی جاتی ہے، جس کے بعد عارضی طور پر سسٹم میں بیع کا اندراج لاک ہو جاتا ہے۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;&lt;strong&gt;فرد برائے ضمانت:&lt;/strong&gt; عدالتی معاملات یا سیکیورٹی ڈپازٹ کے لیے استعمال ہوتی ہے۔&lt;/li&gt;</p><p>&lt;/ol&gt;</p><p><br></p><p>&lt;h3&gt;آن لائن فرد حاصل کرنے کے مراحل&lt;/h3&gt;</p><p>&lt;ol&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;&lt;strong&gt;پی ایل آر اے ایپ یا پورٹل پر لاگ ان:&lt;/strong&gt; پنجاب لینڈ ریکارڈز اتھارٹی کی آفیشل ویب سائٹ یا ڈیجیٹل موبائل ایپ پر اپنا اکاؤنٹ شناختی کارڈ نمبر اور موبائل نمبر کے ذریعے رجسٹر کریں۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;&lt;strong&gt;ضلع اور موضع کا انتخاب:&lt;/strong&gt; جس ضلع، تحصیل اور موضع (علاقے) میں زمین واقع ہے، ڈراپ ڈاؤن لسٹ سے اس کا انتخاب کریں۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;&lt;strong&gt;اراضی کی تلاش:&lt;/strong&gt; آپ تین طریقوں سے اپنی زمین تلاش کر سکتے ہیں: &lt;strong&gt;(1) شناختی کارڈ نمبر&lt;/strong&gt;، &lt;strong&gt;(2) کھیوٹ نمبر&lt;/strong&gt;، یا &lt;strong&gt;(3) خریدار/مالک کے نام&lt;/strong&gt; کے ذریعے۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;&lt;strong&gt;فیس کی ادائیگی بذریعہ ای-پے (1-Link):&lt;/strong&gt; درخواست مکمل ہونے پر سسٹم 17 ہندسوں پر مشتمل پی ایس آئی ڈی (PSID) کوڈ جاری کرے گا۔ یہ فیس (تقریباً 200 سے 500 روپے) آپ ایزی پیسہ، جاز کیش یا کسی بھی بینک کی موبائل ایپ سے 1 منٹ میں ادا کر سکتے ہیں۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;&lt;strong&gt;کیو آر کوڈ والی فرد ڈاؤن لوڈ کریں:&lt;/strong&gt; فیس کی تصدیق ہوتے ہی کیو آر کوڈ کے ساتھ مصدقہ فردِ ملکیت پی ڈی ایف فارمیٹ میں ڈاؤن لوڈ ہو جائے گی جس کا پرنٹ سرکاری سطح پر قابلِ قبول ہے۔&lt;/li&gt;</p><p>&lt;/ol&gt;</p><p><br></p><p>&lt;p&gt;&lt;em&gt;اہم نکتہ: زمین خریدنے سے پہلے بیچنے والے کی فرد پر کیو آر کوڈ اسکین کر کے اس کی تصدیق ضرور کریں تاکہ کسی قسم کے جعلی کاغذات یا دہرے بیعانے سے بچا جا سکے۔&lt;/em&gt;&lt;/p&gt;</p>',
  'Online Fard, PLRA, Arazi Record, Land Verification, Khasra, Khewat,patwari',
  '3',
  '42',
  '0',
  '0',
  'published',
  '2026-10-20 22:36:14',
  '2026-11-01 14:53:31'
)
