-- 3. land-measurement-units-marla-kanal-sarsahi-karam
INSERT INTO `posts` (`id`, `user_id`, `title`, `title_ur`, `slug`, `category`, `featured_image`, `summary`, `summary_ur`, `content`, `content_ur`, `tags`, `read_time`, `views_count`, `likes_count`, `is_featured`, `status`, `created_at`, `updated_at`) VALUES (
  3,
  COALESCE((SELECT u.`id` FROM `users` u WHERE u.`role` = 'admin' ORDER BY u.`id` LIMIT 1), (SELECT MIN(u2.`id`) FROM `users` u2)),
  'Marla, Kanal, Karam and Sarsahi: How Land Is Measured in Punjab',
  'مرلہ، کنال، کرم اور سرساہی کی درست پیمائش کیسے کریں؟ پنجاب کے دونوں رائج معیارات',
  'land-measurement-units-marla-kanal-sarsahi-karam',
  'Investment Tips',
  'blog_images/1792517898_6ad7a70aa5566.jpg',
  'The difference between a 225 sq ft society marla and a 272.25 sq ft revenue marla, plus karam, sarsahi and how to work out your plot size yourself.',
  'پنجاب میں سوسائٹیز کے 225 مربع فٹ مرلہ اور ریونیو پٹواری کے 272 مربع فٹ مرلہ میں کیا فرق ہے؟ کرم اور سرساہی سے پلاٹ کا سائز نکالنے کا سب سے آسان حسابی طریقہ۔',
  '<p>In a property deal, a patwari may talk in karam and sarsahi while a housing society uses square feet and square yards. Knowing the basics yourself can save you from an expensive misunderstanding.</p>\n<h2>Two different marlas</h2>\n<ul>\n<li><strong>Society marla (225 sq ft):</strong> many private housing societies and urban authorities treat 1 marla as 225 sq ft, or 25 square yards. A 5 marla plot is then 1,125 sq ft.</li>\n<li><strong>Revenue marla (272.25 sq ft):</strong> the revenue department and rural land records use 272.25 sq ft. On this scale, 1 kanal is 5,445 sq ft.</li>\n</ul>\n<p>Always ask which marla a seller means, because the same \"5 marla\" can differ by more than 230 sq ft.</p>\n<h2>Traditional revenue units</h2>\n<table>\n<thead><tr><th>Unit</th><th>Equal to</th></tr></thead>\n<tbody>\n<tr><td>Karam (length)</td><td>5.5 feet (66 inches)</td></tr>\n<tr><td>Sarsahi (1 square karam)</td><td>30.25 sq ft</td></tr>\n<tr><td>Marla</td><td>9 sarsahi = 272.25 sq ft</td></tr>\n<tr><td>Kanal</td><td>20 marla = 5,445 sq ft</td></tr>\n<tr><td>Acre</td><td>8 kanal = 43,560 sq ft</td></tr>\n<tr><td>Murabba</td><td>25 acres</td></tr>\n</tbody>\n</table>\n<h2>Work out your plot size</h2>\n<ol>\n<li>Measure the length and width in feet.</li>\n<li>Multiply them. For example, 25 ft × 45 ft = 1,125 sq ft.</li>\n<li>For a society plot, divide by 225: 1,125 ÷ 225 = 5 marla.</li>\n<li>For revenue records, divide by 272.25: 1,125 ÷ 272.25 = about 4.13 marla.</li>\n</ol>\n<h2>Crooked plots</h2>\n<p>This simple method only suits rectangular plots. For an irregular shape, use our free <a href=\"https://www.assanzameen.com/tools/patwari-land-converter\">Land Unit Converter</a>, which converts units and estimates area from the four sides and a diagonal. For a registry or dispute, get the final measurement from the patwari or a licensed surveyor.</p>\n<h2>More help</h2>\n<p>Open our <a href=\"https://www.assanzameen.com/tools/government-links\">Government Links Guide</a> to see all the official portals in one place. To contact PLRA or make a complaint, call <strong>(042) 111-22-22-77</strong> (Monday to Saturday, 8:00 AM to 5:00 PM).</p>\n<blockquote>This article was written on 1 November 2026 from information on the PLRA website. Assan Zameen is not a government body. Fees and procedures can change, so confirm with the relevant office before paying. This is not legal advice.</blockquote>',
  '<p>&lt;h2&gt;اراضی و پلاٹ کی روایتی پیمائش: کرم، سرساہی، مرلہ اور کنال کا حسابی فارمولا&lt;/h2&gt;</p><p><br></p><p>&lt;p&gt;پراپرٹی کا سودا کرتے وقت اکثر خریداروں کو رقبے کی پیمائش سمجھنے میں دشواری پیش آتی ہے۔ کبھی پٹواری کرم اور سرساہی میں بات کرتا ہے، تو کبھی ہاؤسنگ سوسائٹیز میں مربع گز اور مربع فٹ کا پیمانہ استعمال ہوتا ہے۔ اراضی کے معاملات میں نقصان سے بچنے کے لیے ضروری ہے کہ آپ کو زمین کی بنیادی پیمائش کا حساب خود کرنا آتا ہو۔&lt;/p&gt;</p><p><br></p><p>&lt;h3&gt;پنجاب میں مرلے کے دو مختلف معیارات&lt;/h3&gt;</p><p>&lt;p&gt;پنجاب میں اس وقت رقبے کے دو معیار رائج ہیں جن کا فرق سمجھنا انتہائی ضروری ہے:&lt;/p&gt;</p><p>&lt;ul&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;&lt;strong&gt;1. سوسائٹی مرلہ (225 مربع فٹ):&lt;/strong&gt; لاہور، فیصل آباد اور راولپنڈی کی زیادہ تر پرائیویٹ ہاؤسنگ سوسائٹیز اور شہری اتھارٹیز (جیسے ایل ڈی اے یا ایف ڈی اے) میں 1 مرلہ &lt;strong&gt;225 مربع فٹ&lt;/strong&gt; (یعنی 25 مربع گز) کے برابر مانا جاتا ہے۔ اس لحاظ سے 5 مرلہ کا پلاٹ 1125 مربع فٹ بنتا ہے۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;&lt;strong&gt;2. سرکاری پٹواری / ریونیو مرلہ (272.25 مربع فٹ):&lt;/strong&gt; محکمہ مال (بورڈ آف ریونیو)، دیہی علاقوں اور زرعی اراضی کے سرکاری کاغذات میں 1 مرلہ &lt;strong&gt;272.25 مربع فٹ&lt;/strong&gt; کے برابر ہوتا ہے۔ اس پیمانے پر 1 کنال میں 5445 مربع فٹ رقبہ بنتا ہے۔&lt;/li&gt;</p><p>&lt;/ul&gt;</p><p><br></p><p>&lt;h3&gt;روایتی پٹواری پیمائش کی اکائیاں&lt;/h3&gt;</p><p>&lt;ol&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;&lt;strong&gt;کرم (Karam):&lt;/strong&gt; پٹواری پیمائش میں لمبائی کا بنیادی پیمانہ \"کرم\" کہلاتا ہے جو ساڑھے پانچ فٹ (5.5 Feet / 66 Inches) کے برابر ہوتا ہے۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;&lt;strong&gt;مربع کرم:&lt;/strong&gt; اگر لمبائی اور چوڑائی ایک ایک کرم ہو تو وہ 1 مربع کرم بنتا ہے، یعنی &lt;strong&gt;30.25 مربع فٹ&lt;/strong&gt;۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;&lt;strong&gt;سرساہی (Sarsahi):&lt;/strong&gt; 1 مربع کرم کو ہی 1 سرساہی کہا جاتا ہے۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;&lt;strong&gt;مرلہ:&lt;/strong&gt; 9 سرساہی (یعنی 9 مربع کرم) مل کر 1 مرلہ بناتے ہیں۔ (9 × 30.25 = 272.25 مربع فٹ)۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;&lt;strong&gt;کنال:&lt;/strong&gt; 20 مرلے مل کر 1 کنال بناتے ہیں۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;&lt;strong&gt;مربع یا ایکڑ:&lt;/strong&gt; 8 کنال مل کر 1 ایکڑ (قلعہ) بناتے ہیں، جبکہ 25 ایکڑ پر 1 مربع بنتا ہے۔&lt;/li&gt;</p><p>&lt;/ol&gt;</p><p><br></p><p>&lt;h3&gt;پلاٹ کا رقبہ خود نکالنے کا آسان طریقہ&lt;/h3&gt;</p><p>&lt;p&gt;اگر آپ کے پاس فٹا یا فیتہ موجود ہے تو اپنے پلاٹ کی لمبائی اور چوڑائی فٹوں میں ناپیں:&lt;/p&gt;</p><p>&lt;ol&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;لمبائی کو چوڑائی سے ضرب دے کر کل مربع فٹ نکالیں (مثال: 25 فٹ چوڑائی × 45 فٹ لمبائی = 1125 مربع فٹ)۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;اگر سوسائٹی کا پلاٹ ہے تو کل مربع فٹ کو &lt;strong&gt;225&lt;/strong&gt; پر تقسیم کریں (1125 ÷ 225 = 5 مرلہ)۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;اگر رجسٹری یا دیہی کھاتہ ہے تو کل مربع فٹ کو &lt;strong&gt;272.25&lt;/strong&gt; پر تقسیم کریں۔&lt;/li&gt;</p><p>&lt;/ol&gt;</p><p><br></p><p>&lt;p&gt;&lt;em&gt;نوٹ: فیلڈ میں موقع پر کھڑے ہو کر فوری اور درست پیمائش کے لیے آسان زمین کا پٹواری لینڈ کیلکولیٹر استعمال کریں، جو کرم اور سرساہی کو ایک کلک پر مرلہ اور کنال میں تبدیل کر دیتا ہے۔&lt;/em&gt;&lt;/p&gt;</p>',
  'Land Measurement, Marla, Kanal, Karam, Sarsahi, Square Feet, Patwari Units',
  '6',
  '9',
  '0',
  '0',
  'published',
  '2026-10-20 22:38:18',
  '2026-11-01 14:53:30'
)
