  `title` = VALUES(`title`), `title_ur` = VALUES(`title_ur`), `summary` = VALUES(`summary`), `summary_ur` = VALUES(`summary_ur`), `content` = VALUES(`content`), `content_ur` = VALUES(`content_ur`),
