-- 4. punjab-e-abiana-online-tax-payment-easypaisa-guide
INSERT INTO `posts` (`id`, `user_id`, `title`, `title_ur`, `slug`, `category`, `featured_image`, `summary`, `summary_ur`, `content`, `content_ur`, `tags`, `read_time`, `views_count`, `likes_count`, `is_featured`, `status`, `created_at`, `updated_at`) VALUES (
  4,
  COALESCE((SELECT u.`id` FROM `users` u WHERE u.`role` = 'admin' ORDER BY u.`id` LIMIT 1), (SELECT MIN(u2.`id`) FROM `users` u2)),
  'Punjab e-Abiana: How to Check and Pay Your Canal Water Bill Online',
  'پنجاب ای-آبیانہ سسٹم: زرعی زمین کے آبیانہ ٹیکس کی آن لائن تصدیق اور ایزی پیسہ سے ادائیگی کا طریقہ',
  'punjab-e-abiana-online-tax-payment-easypaisa-guide',
  'Taxes & Laws',
  'blog_images/1792579602_6ad89812037c3.jpg',
  'How farmers in Punjab can check their e-Abiana canal water bill and pay it with a PSID through Easypaisa, JazzCash or a banking app.',
  ' پنجاب اریگیشن ڈیپارٹمنٹ کے تحت نہری پانی کا ای-آبیانہ بل آن لائن کیسے چیک کریں؟ پٹواری کے پاس جائے بغیر ایزی پیسہ، جاز کیش اور 1-Link سے گھر بیٹھے بل ادا کرنے کا آسان طریقہ۔',
  '<p>The Punjab Irrigation Department has moved abiana, the charge for canal water, to a digital system. Farmers can now check their bill and pay it from a phone instead of relying only on paper slips.</p>\n<h2>What is e-Abiana?</h2>\n<p>It is the digital abiana system that links canal-irrigated land with the farmer\'s details. A computerized bill is issued for each crop season.</p>\n<h2>How to check your bill</h2>\n<ol>\n<li>Open the Irrigation Department\'s e-Abiana portal or the e-Pay Punjab app.</li>\n<li>Select your district, tehsil and mouza.</li>\n<li>Enter your canal account number or CNIC.</li>\n<li>The system shows your area, the amount due and a PSID challan number.</li>\n</ol>\n<h2>How to pay</h2>\n<ol>\n<li>Open Easypaisa, JazzCash or your banking app.</li>\n<li>Go to government payments or e-Pay Punjab.</li>\n<li>Choose e-Abiana if it is listed, and enter your PSID.</li>\n<li>Check that the name and amount are correct, then pay.</li>\n<li>Save the digital receipt.</li>\n</ol>\n<p>App menus differ and can change, so if you cannot find the option, ask your bank or the Irrigation Department. You can also check the official <a href=\"https://epay.punjab.gov.pk/\" rel=\"noopener\" target=\"_blank\">e-Pay Punjab website</a>.</p>\n<h2>If the bill looks wrong</h2>\n<p>If the area or amount looks wrong, do not ignore it. Contact your local Irrigation Department office with your account details and last receipt, and keep all your payment records.</p>\n<h2>Why keep your payments up to date?</h2>\n<p>Clear records help avoid disputes and surprises when you deal with your land. If you plan to sell, ask your Arazi Record Centre whether any dues need clearing, and get a <a href=\"https://www.assanzameen.com/blog/fard-kaise-hasil-karein-punjab-online-arc-guide\">fresh fard</a>.</p>\n<h2>More help</h2>\n<p>Open our <a href=\"https://www.assanzameen.com/tools/government-links\">Government Links Guide</a> to see all the official portals in one place. To contact PLRA or make a complaint, call <strong>(042) 111-22-22-77</strong> (Monday to Saturday, 8:00 AM to 5:00 PM).</p>\n<blockquote>This article was written on 1 November 2026 from information on the PLRA website. Assan Zameen is not a government body. Fees and procedures can change, so confirm with the relevant office before paying. This is not legal advice.</blockquote>',
  '<p>&lt;h2&gt;پنجاب ای-آبیانہ (e-Abiana) سسٹم: زرعی زمین کے پانی کا بل اب گھر بیٹھے ادا کریں&lt;/h2&gt;</p><p><br></p><p>&lt;p&gt;محکمہ آبپاشی حکومت پنجاب (Punjab Irrigation Department) نے صدیوں پرانے نہری پانی کے آبیانہ ٹیکس نظام کو ڈیجیٹل کر کے \"ای-آبیانہ سسٹم\" میں تبدیل کر دیا ہے۔ پہلے کسانوں اور زمینداروں کو نہری پٹواری کے پاس جا کر پرچی بنوانی پڑتی تھی اور اکثر غلط پیمائش یا بقایا جات کے جھگڑے پیدا ہوتے تھے۔ اب ہر کاشتکار اپنے موبائل سے براہِ راست نہری پانی کا بل چیک کر کے فوراً ادا کر سکتا ہے۔&lt;/p&gt;</p><p><br></p><p>&lt;h3&gt;ای-آبیانہ سسٹم کیا ہے؟&lt;/h3&gt;</p><p>&lt;p&gt;ای-آبیانہ پنجاب انفارمیشن ٹیکنالوجی بورڈ (PITB) اور محکمہ انہار کا مشترکہ منصوبہ ہے، جس میں پنجاب کی تمام نہروں سے سیراب ہونے والی اراضی کو کھتونی، خسرہ اور کاشتکار کے شناختی کارڈ کے ساتھ منسلک کر دیا گیا ہے۔ اب سال میں دو بار (ربیع اور خریف کی فصلوں کے بعد) کسان کو کمپیوٹرائزڈ بل جاری ہوتا ہے۔&lt;/p&gt;</p><p><br></p><p>&lt;h3&gt;آن لائن بل چیک کرنے کا طریقہ کار&lt;/h3&gt;</p><p>&lt;ol&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;محکمہ آبپاشی پنجاب کے ای-آبیانہ پورٹل یا e-Pay Punjab ایپ کو اوپن کریں۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;اپنا ضلع، تحصیل اور موضع (دیہہ) منتخب کریں۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;اپنا نہری کھاتہ نمبر یا کسان شناختی کارڈ نمبر درج کریں۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;سسٹم فوراً آپ کے رقبے، نہری باری اور واجب الادا آبیانہ رقم کی سمری کے ساتھ 17 ہندسوں کا چالان نمبر (PSID) ظاہر کر دے گا۔&lt;/li&gt;</p><p>&lt;/ol&gt;</p><p><br></p><p>&lt;h3&gt;ایزی پیسہ اور جاز کیش سے ادائیگی کا طریقہ&lt;/h3&gt;</p><p>&lt;ol&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;اپنی &lt;strong&gt;Easypaisa&lt;/strong&gt; یا &lt;strong&gt;JazzCash&lt;/strong&gt; ایپ کھولیں۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;&lt;strong&gt;Govt Payments / e-Pay Punjab&lt;/strong&gt; کے آپشن پر کلک کریں۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;لسٹ میں سے &lt;strong&gt;\"e-Abiana\"&lt;/strong&gt; منتخب کریں۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;اپنا 17 ہندسوں کا PSID چالان نمبر درج کریں؛ کسان کا نام اور بل کی اصل رقم سکرین پر آ جائے گی۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;\"Pay Now\" پر کلک کریں؛ بل فورا کلیئر ہو جائے گا اور آپ کو ڈیجیٹل ادائیگی رسید موصول ہو جائے گی۔&lt;/li&gt;</p><p>&lt;/ol&gt;</p><p><br></p><p>&lt;p&gt;&lt;em&gt;اہم فائدہ: آن لائن ای-آبیانہ ادا کرنے سے محکمہ انہار کے ریکارڈ میں آپ کا کھاتہ 1 سیکنڈ میں کلیئر ہو جاتا ہے اور زمین کی فرد برائے بیع نکلوانے میں کوئی رکاوٹ پیش نہیں آتی۔&lt;/em&gt;&lt;/p&gt;</p>',
  'E Abiana, Agriculture Tax, Punjab Irrigation, Easypaisa Payment, PSID, Fard, Khasra',
  '3',
  '19',
  '0',
  '0',
