-- 5. overseas-pakistanis-online-land-record-poa-verification
INSERT INTO `posts` (`id`, `user_id`, `title`, `title_ur`, `slug`, `category`, `featured_image`, `summary`, `summary_ur`, `content`, `content_ur`, `tags`, `read_time`, `views_count`, `likes_count`, `is_featured`, `status`, `created_at`, `updated_at`) VALUES (
  5,
  COALESCE((SELECT u.`id` FROM `users` u WHERE u.`role` = 'admin' ORDER BY u.`id` LIMIT 1), (SELECT MIN(u2.`id`) FROM `users` u2)),
  'Overseas Pakistanis and Property in Punjab: Power of Attorney and Land Records',
  'اوورسیز پاکستانیوں کے لیے آن لائن اراضی سروسز: بیرونِ ملک سے پاکستان میں پلاٹ کی تصدیق اور پاور آف اٹارنی کا طریقہ',
  'overseas-pakistanis-online-land-record-poa-verification',
  'Property Guides',
  'blog_images/1792595103_6ad8d49f7e8e4.jpg',
  'How overseas Pakistanis can protect property in Punjab: digital power of attorney, MOFA verification, online fard and recording statements from abroad.',
  'بیرونِ ملک مقیم پاکستانی بغیر پاکستان آئے اپنے پلاٹس اور زرعی اراضی کا ریکارڈ کیسے چیک کریں؟ نادرا ڈیجیٹل پاور آف اٹارنی اور قونصل خانے کی تصدیق کے بعد زمین بیچنے کا آسان حل۔',
  '<p>Overseas Pakistanis invest heavily in property back home, and their land has often been a target for fake powers of attorney. Digital services now make it easier to manage and watch over property from abroad.</p>\n<h2>Digital power of attorney</h2>\n<p>If you want a relative or trusted person to act for you, NADRA and the Ministry of Foreign Affairs offer a digital process, so you may not need to travel. It generally involves:</p>\n<ol>\n<li>An online application with your NICOP, your attorney\'s CNIC and the property details.</li>\n<li>Biometric verification through NADRA\'s Pak ID mobile app.</li>\n<li>An interview with a consular officer at a Pakistan mission.</li>\n<li>Verification through MOFA.</li>\n</ol>\n<p>Check the current steps with NADRA or your nearest mission before starting.</p>\n<h2>What PLRA requires</h2>\n<p>PLRA says a valid, attested power of attorney must be verified by MOFA and authenticated by the Sub-Registrar in Pakistan. After that, a fard can be issued against it.</p>\n<h2>Giving your statement from abroad</h2>\n<ul>\n<li><strong>Mutation:</strong> a representative at the Pakistan mission records your statement as commission for the Revenue Officer. Parties in Punjab appear before the Revenue Officer.</li>\n<li><strong>Registered deed:</strong> the Sub-Registrar appoints the mission official as commission to record your statement, including thumb impression, photo and video.</li>\n</ul>\n<h2>Other services from abroad</h2>\n<ul>\n<li>Apply for a <a href=\"https://www.assanzameen.com/blog/fard-kaise-hasil-karein-punjab-online-arc-guide\">fard</a> online.</li>\n<li>Generate <a href=\"https://www.assanzameen.com/blog/e-stamp-challan-32a-kaise-banayein-punjab-guide\">e-Stamp challans</a> and pay through authorized channels or a representative.</li>\n<li>Apply for <a href=\"https://www.assanzameen.com/blog/zameen-ki-taqseem-online-darkhwast-punjab\">partition</a> and authorize a local representative for field work.</li>\n</ul>\n<h2>A simple way to stay safe</h2>\n<p>If you have empty land or a vacant plot, check a fresh fard regularly, at least twice a year, to make sure nothing has changed in the record. Give a power of attorney only to someone you fully trust, and limit it to what is needed.</p>\n<h2>More help</h2>\n<p>Open our <a href=\"https://www.assanzameen.com/tools/government-links\">Government Links Guide</a> to see all the official portals in one place. To contact PLRA or make a complaint, call <strong>(042) 111-22-22-77</strong> (Monday to Saturday, 8:00 AM to 5:00 PM).</p>\n<blockquote>This article was written on 1 November 2026 from information on the PLRA website. Assan Zameen is not a government body. Fees and procedures can change, so confirm with the relevant office before paying. This is not legal advice.</blockquote>',
  '<p>&lt;h2&gt;اوورسیز پاکستانی اور جائیداد کی حفاظت: آن لائن پاور آف اٹارنی اور فرد کے حصول کی گائیڈ&lt;/h2&gt;</p><p><br></p><p>&lt;p&gt;بیرونِ ملک مقیم پاکستانی ملک کی معیشت کا سب سے بڑا ستون ہیں اور ان کی کمائی کا ایک بڑا حصہ پاکستان میں ریئل اسٹیٹ سیکٹر میں انویسٹ ہوتا ہے۔ ماضی میں اوورسیز پاکستانیوں کی جائیدادوں پر رشتے داروں یا قبضہ مافیا کی جانب سے جعلی مختار نامہ (Power of Attorney) بنا کر زمین ہتھیانے کے بے شمار واقعات پیش آتے تھے۔ لیکن اب نادرا اور وزارتِ خارجہ (MOFA) کے آن لائن سسٹم نے یہ تمام راستے بند کر دیے ہیں۔&lt;/p&gt;</p><p><br></p><p>&lt;h3&gt;نادرا ڈیجیٹل پاور آف اٹارنی (Digital POA) کیا ہے؟&lt;/h3&gt;</p><p>&lt;p&gt;اب اگر کوئی اوورسیز پاکستانی امریکہ، برطانیہ، یورپ یا خلیجی ممالک میں بیٹھ کر پاکستان میں موجود اپنے بھائی، والد یا کسی معتمد شخص کو پلاٹ بیچنے یا کیس لڑنے کا اختیار دینا چاہتا ہے، تو اسے پاکستان آنے کی ضرورت نہیں ہے۔ نادرا کا ڈیجیٹل پورٹل اس کا آن لائن حل فراہم کرتا ہے۔&lt;/p&gt;</p><p><br></p><p>&lt;h3&gt;آن لائن مختار نامہ بنوانے کے 4 آسان مراحل&lt;/h3&gt;</p><p>&lt;ol&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;&lt;strong&gt;آن لائن درخواست:&lt;/strong&gt; نادرا کی ڈیجیٹل POA ویب سائٹ پر جا کر اکاؤنٹ بنائیں اور اپنے نائیکوپ (NICOP)، مختار عام/خاص بننے والے شخص کے شناختی کارڈ اور پراپرٹی کی فرد کا اندراج کریں۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;&lt;strong&gt;بائیو میٹرک فنگر پرنٹس:&lt;/strong&gt; نادرا کی پاک آئی ڈی موبائل ایپ کے ذریعے اوورسیز شہری موبائل کیمرے سے اپنے فنگر پرنٹس براہِ راست اسکین کر کے تصدیق کرے گا۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;&lt;strong&gt;قونصل خانے کے ساتھ ویڈیو انٹرویو:&lt;/strong&gt; پاکستانی سفارت خانے کا قونصلر افسر ویڈیو لنک پر اوورسیز پاکستانی سے آمنے سامنے بات کرے گا اور اس کی رضا مندی ریکارڈ کرے گا کہ آیا وہ ہوش و حواس میں یہ اختیار دے رہا ہے۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;&lt;strong&gt;وزارتِ خارجہ (MOFA) کی آٹو تصدیق:&lt;/strong&gt; ویڈیو انٹرویو مکمل ہوتے ہی ڈیجیٹل پاور آف اٹارنی پاکستان میں وزارتِ خارجہ کے سسٹم کو بھیج دی جاتی ہے، جہاں سے مجاز شخص فوری تصدیق کروا کر سب رجسٹرار آفس میں رجسٹری کروا سکتا ہے۔&lt;/li&gt;</p><p>&lt;/ol&gt;</p><p><br></p><p>&lt;p&gt;&lt;em&gt;محفوظ رہنے کا اصول: اپنی غیر آباد زمین یا خالی پلاٹ کی سال میں کم از کم دو مرتبہ آن لائن فرد چیک کرتے رہیں تاکہ اس بات کا اطمینان رہے کہ ریکارڈ میں کوئی غیر قانونی ردوبدل نہیں ہوا۔&lt;/em&gt;&lt;/p&gt;</p>',
  'Overseas Pakistanis, Power of Attorney, NADRA POA, Embassy Attestation, PLRA Overseas, Foreign Investment',
  '6',
  '17',
  '0',
  '0',
  'published',
  '2026-10-22 01:03:48',
  '2026-11-01 14:53:27'
)
