-- 6. property-bayana-token-money-cancellation-legal-rights-pakistan
INSERT INTO `posts` (`id`, `user_id`, `title`, `title_ur`, `slug`, `category`, `featured_image`, `summary`, `summary_ur`, `content`, `content_ur`, `tags`, `read_time`, `views_count`, `likes_count`, `is_featured`, `status`, `created_at`, `updated_at`) VALUES (
  6,
  COALESCE((SELECT u.`id` FROM `users` u WHERE u.`role` = 'admin' ORDER BY u.`id` LIMIT 1), (SELECT MIN(u2.`id`) FROM `users` u2)),
  'Bayana and Token Money in Pakistan: What Happens If a Property Deal Is Cancelled?',
  'بیعانہ کرتے وقت کچے کاغذ سے پرہیز: پراپرٹی ڈیل کینسل ہونے کی صورت میں ٹوکن رقم کی واپسی کے قانونی اصول',
  'property-bayana-token-money-cancellation-legal-rights-pakistan',
  'Property Guides',
  'blog_images/1792595372_6ad8d5ac1fc47.jpg',
  'Token money vs a bayana agreement, what usually happens if a buyer or seller backs out, and how to protect your advance payment in a property deal.',
  'پلاٹ کا سودا کرتے وقت کچے کاغذ یا زبانی بات چیت پر ٹوکن دینا کتنا خطرناک ہے؟ اگر خریدار یا بیچنے والا مقررہ تاریخ سے مکر جائے تو بیعانہ ضبط کرنے یا دوگنا واپس لینے کا درست قانونی طریقہ۔',
  '<p>Many property disputes in Pakistan begin because the deal was never properly written down. A buyer hands over cash, the owner later backs out, and there is no proof. Here is how to protect yourself.</p>\n<h2>Token money and a bayana agreement</h2>\n<ul>\n<li><strong>Token money:</strong> a small initial payment showing serious intent, so the owner stops negotiating with others. It is usually for a few days only.</li>\n<li><strong>Bayana agreement:</strong> a written agreement, usually on stamp paper, recording a larger advance payment and a date for the registry. In practice, parties often agree around 10 to 25 percent and 30 to 60 days.</li>\n</ul>\n<h2>If the deal is cancelled</h2>\n<p>What happens depends mostly on <strong>what your agreement says</strong> and the facts of your case, which a court may review under the Contract Act 1872 and related law.</p>\n<ul>\n<li><strong>If the buyer backs out:</strong> agreements often allow the seller to keep the bayana, so a clear written clause is important.</li>\n<li><strong>If the seller backs out:</strong> agreements often require the seller to return the bayana plus an equal amount as a penalty. The buyer may also be able to ask a court to enforce the sale.</li>\n</ul>\n<p>These are common terms, not automatic rights. Have a lawyer check your clauses before you sign.</p>\n<h2>The safest way to pay</h2>\n<ol>\n<li>Do not pay cash without proof. Use a pay order, crossed cheque or bank transfer.</li>\n<li>Attach the payment record to the agreement.</li>\n<li>Have two adult witnesses sign with thumb impressions.</li>\n<li>Check the <a href=\"https://www.assanzameen.com/blog/fard-kaise-hasil-karein-punjab-online-arc-guide\">latest fard</a> before paying, to be sure the seller is the owner.</li>\n</ol>\n<p>Our <a href=\"https://www.assanzameen.com/tools/bayana-deed-generator\">Bayana Agreement Maker</a> prepares an Urdu draft to review with your lawyer and print on e-stamp paper.</p>\n<h2>More help</h2>\n<p>Open our <a href=\"https://www.assanzameen.com/tools/government-links\">Government Links Guide</a> to see all the official portals in one place. To contact PLRA or make a complaint, call <strong>(042) 111-22-22-77</strong> (Monday to Saturday, 8:00 AM to 5:00 PM).</p>\n<blockquote>This article was written on 1 November 2026 from information on the PLRA website. Assan Zameen is not a government body. Fees and procedures can change, so confirm with the relevant office before paying. This is not legal advice.</blockquote>',
  '<p>&lt;h2&gt;پراپرٹی بیعانہ و ٹوکن: رقم کے لین دین میں قانونی غلطیاں اور تنازعات کا حل&lt;/h2&gt;</p><p><br></p><p>&lt;p&gt;پاکستان کی پراپرٹی مارکیٹ میں تنازعات اور عدالتوں میں زیرِ التوا مقدمات کی ایک بڑی وجہ جائیداد کا سودا کرتے وقت باقاعدہ قانونی معاہدہ نہ لکھنا ہے۔ کچہری اور تھانوں میں اکثر ایسی شکایات آتی ہیں کہ خریدار نے 2 لاکھ روپے نقد دیے، مگر بعد میں مالک مکان مکر گیا اور رقم واپس کرنے سے انکار کر دیا۔ اگر آپ زمین یا مکان کی خرید و فروخت کر رہے ہیں تو یہ قانونی اصول اپنے پلے باندھ لیں۔&lt;/p&gt;</p><p><br></p><p>&lt;h3&gt;1. \"سر دستی ٹوکن\" اور \"باقاعدہ بیعانہ\" میں فرق&lt;/h3&gt;</p><p>&lt;ul&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;&lt;strong&gt;سر دستی ٹوکن (Token Money):&lt;/strong&gt; یہ ایک ابتدائی نیت کی تصدیق ہوتی ہے تاکہ مالک اس پراپرٹی کی کسی اور سے بات نہ کرے۔ یہ رقم عموماً 50 ہزار سے 1 لاکھ روپے ہوتی ہے اور اس کی میعاد زیادہ سے زیادہ 3 سے 7 دن رکھی جاتی ہے۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;&lt;strong&gt;اقرار نامہ بیعانہ (Bayana Agreement):&lt;/strong&gt; یہ باضابطہ قانونی دستاویز ہے جو اسٹامپ پیپر پر تحریر ہوتی ہے، جس میں کل قیمت کا 10 سے 25 فیصد ادا کیا جاتا ہے اور رجسٹری کے لیے 30 سے 60 دن کا وقت مقرر ہوتا ہے۔&lt;/li&gt;</p><p>&lt;/ul&gt;</p><p><br></p><p>&lt;h3&gt;2. معاہدہ کینسل ہونے کی صورت میں قانون کیا کہتا ہے؟&lt;/h3&gt;</p><p>&lt;p&gt;کنٹریکٹ ایکٹ 1872 اور ملکی عدالتی نظائر کے مطابق بیعانے کی شرائط درج ذیل اصولوں پر نافذ ہوتی ہیں:&lt;/p&gt;</p><p>&lt;ol&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;&lt;strong&gt;اگر خریدار مکر جائے:&lt;/strong&gt; اگر خریدار مقررہ تاریخ تک بقیہ رقم کا بندوبست نہ کر سکے یا سودے سے پیچھے ہٹ جائے، تو بیچنے والے کو یہ حق حاصل ہوتا ہے کہ وہ بیعانہ کی رقم ضبط کر لے، بشرطیکہ یہ شق تحریری اقرار نامے میں واضح لکھی گئی ہو۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;&lt;strong&gt;اگر بیچنے والا (مالک) مکر جائے:&lt;/strong&gt; اگر مالک کسی دوسرے گاہک سے زیادہ قیمت ملنے پر یا کسی اور وجہ سے رجسٹری کروانے سے انکار کر دے، تو قانون کے مطابق وہ اصل بیعانہ واپس کرنے کے ساتھ اتنی ہی رقم بطور ہرجانہ (یعنی دوگنا بیعانہ) ادا کرنے کا پابند ہوتا ہے۔&lt;/li&gt;</p><p>&lt;/ol&gt;</p><p><br></p><p>&lt;h3&gt;3. محفوظ ترین طریقہ کیا ہے؟&lt;/h3&gt;</p><p>&lt;p&gt;کبھی بھی کیش رقم کی لین دین بغیر ثبوت کے نہ کریں۔ ہمیشہ ٹوکن یا بیعانہ کی ادائیگی بینک پے آرڈر، کراس چیک یا آن لائن بینک ٹرانسفر کے ذریعے کریں اور ٹرانزیکشن کی رسید اقرار نامے کے ساتھ منسلک کریں۔ اس کے علاوہ تحریر پر دو عاقل و بالغ گواہان کے انگوٹھے اور دستخط لازماً ثبت کروائیں۔&lt;/p&gt;</p><p><br></p><p>&lt;p&gt;&lt;em&gt;یاد رکھیں: آسان زمین کا بیعانہ جنریٹر ٹول سیکنڈوں میں قانونی شقوں کے ساتھ پی ڈی ایف اقرار نامہ تیار کر دیتا ہے تاکہ آپ کی جمع پونجی ہمیشہ قانونی تحفظ میں رہے۔&lt;/em&gt;&lt;/p&gt;</p>',
  'Bayana Agreement, Token Money, Property Cancellation, Legal Stamp Paper, Breach of Contract, Token Forfeiture',
  '5',
  '19',
  '0',
  '0',
  'published',
  '2026-10-22 01:09:32',
  '2026-11-01 14:53:25'
)
