-- 7. punjab-green-property-certificate-plra-complete-guide
INSERT INTO `posts` (`id`, `user_id`, `title`, `title_ur`, `slug`, `category`, `featured_image`, `summary`, `summary_ur`, `content`, `content_ur`, `tags`, `read_time`, `views_count`, `likes_count`, `is_featured`, `status`, `created_at`, `updated_at`) VALUES (
  7,
  COALESCE((SELECT u.`id` FROM `users` u WHERE u.`role` = 'admin' ORDER BY u.`id` LIMIT 1), (SELECT MIN(u2.`id`) FROM `users` u2)),
  'Green Property Certificate in Punjab: Fee, Process and How to Apply',
  'پنجاب گرین پراپرٹی سرٹیفکیٹ: اراضی ریکارڈ سنٹر سے زمین کے قبضہ، حدود اور جی پی ایس میپ کا تصدیقی سرٹیفکیٹ حاصل کرنے کا طریقہ',
  'punjab-green-property-certificate-plra-complete-guide',
  'Property Guides',
  'blog_images/1792597550_6ad8de2e86018.jpg',
  'What the PLRA Green Property Certificate (GPC) is, how to apply at an Arazi Record Centre, the fee, neighbour statements, refusal and appeal.',
  'پنجاب لینڈ ریکارڈز اتھارٹی (PLRA) کے نئے فیس شیڈول کے تحت گرین پراپرٹی سرٹیفکیٹ (GPC) کا اجراء۔ روایتی فرد کے مقابلے میں یہ سرٹیفکیٹ کیوں زیادہ محفوظ ہے اور 950 روپے فیس کے ساتھ اسے کیسے حاصل کیا جا سکتا ہے۔',
  '<p>A fard shows what the record says, but it may not settle who actually holds the land. PLRA\'s <strong>Green Property Certificate (GPC)</strong> is meant to close that gap.</p>\n<h2>What is a GPC?</h2>\n<p>According to PLRA, it is an electronically generated ownership document that verifies the legal status, ownership and possession of a specific piece of land.</p>\n<h2>How to apply</h2>\n<ol>\n<li><strong>Visit an Arazi Record Centre:</strong> you must go in person to the nearest centre.</li>\n<li><strong>Identity check:</strong> the officer checks your original CNIC, completes NADRA biometric verification and verifies your registered mobile number.</li>\n<li><strong>Pay the fee:</strong> the initial processing fee is listed as <strong>Rs. 900</strong>, payable at a Bank of Punjab counter or branch, or through PSID using JazzCash, EasyPaisa or online banking.</li>\n<li><strong>Record review:</strong> officials match your details with land records, review the ownership history and check for tax liabilities, bank mortgages and court orders.</li>\n<li><strong>Neighbour statements:</strong> at least two neighbouring landowners, whose records are in the computerized system, give statements before the Assistant Director Land Records with biometric verification. This confirms you are in possession.</li>\n<li><strong>Final approval:</strong> the ADLR or an authorized officer reviews the case and approves it.</li>\n</ol>\n<p>Once the process begins, other transactions on the property are temporarily suspended.</p>\n<h2>Joint owners</h2>\n<p>For agricultural land, all co-owners must consent. Without that consent, a legal <a href=\"https://www.assanzameen.com/blog/zameen-ki-taqseem-online-darkhwast-punjab\">partition</a> must be completed first.</p>\n<h2>If your application is refused</h2>\n<p>You receive a refusal letter with the reasons. You can appeal to the Assistant Commissioner within 30 days, or apply again once the cause is resolved.</p>\n<h2>How to verify a GPC</h2>\n<p>A GPC is system-generated and needs no signature or stamp. Verify it by scanning its QR code.</p>\n<h2>Should you rely on it when buying?</h2>\n<p>A GPC is a strong official record, but still scan its QR code, get a fresh fard and take legal advice. <a href=\"https://www.punjab-zameen.gov.pk/gpcinfo\" rel=\"noopener\" target=\"_blank\">Read the official PLRA guide</a>.</p>\n<h2>More help</h2>\n<p>Open our <a href=\"https://www.assanzameen.com/tools/government-links\">Government Links Guide</a> to see all the official portals in one place. To contact PLRA or make a complaint, call <strong>(042) 111-22-22-77</strong> (Monday to Saturday, 8:00 AM to 5:00 PM).</p>\n<blockquote>This article was written on 1 November 2026 from information on the PLRA website. Assan Zameen is not a government body. Fees and procedures can change, so confirm with the relevant office before paying. This is not legal advice.</blockquote>',
  '<p>&lt;h2&gt;پنجاب گرین پراپرٹی سرٹیفکیٹ (GPC): اراضی کی ملکیت اور قبضہ کا سب سے مضبوط ثبوت&lt;/h2&gt;</p><p><br></p><p>&lt;p&gt;پنجاب لینڈ ریکارڈز اتھارٹی (PLRA) نے زمین اور پلاٹس کی خرید و فروخت میں دھوکہ دہی، دہرے قبضے اور جعلی دستاویزات کو جڑ سے اکھاڑنے کے لیے &lt;strong&gt;گرین پراپرٹی سرٹیفکیٹ (Green Property Certificate - GPC)&lt;/strong&gt; کا نظام متعارف کروایا ہے۔ پرانی فردِ ملکیت صرف یہ بتاتی تھی کہ کاغذات میں آپ کا کتنا حصہ ہے، مگر یہ ثابت نہیں کرتی تھی کہ زمین کے اس ٹکڑے پر عملاً قبضہ کس کا ہے اور اس کی چاردیواری کی اصل حدود کیا ہیں۔ گرین سرٹیفکیٹ اس کمی کو دور کرتا ہے۔&lt;/p&gt;</p><p><br></p><p>&lt;h3&gt;گرین پراپرٹی سرٹیفکیٹ کیا ہے؟&lt;/h3&gt;</p><p>&lt;p&gt;یہ پی ایل آر اے کی جانب سے جاری کردہ ایک مستند ڈیجیٹل سرٹیفکیٹ ہے جس میں نہ صرف نادرا سے بائیو میٹرک تصدیق شدہ مالک کا نام ہوتا ہے، بلکہ جی پی ایس (GPS) سیٹلائٹ میپ کے ذریعے زمین کی حدود (Parcel Boundary) اور موقع پر فیلڈ ریونیو افسر کی تصدیق شدہ رپورٹ درج ہوتی ہے۔ اس سرٹیفکیٹ کے حامل پلاٹ پر کوئی قبضہ مافیا یا دوسرا دعویدار جعلی کھاتہ نہیں کھول سکتا۔&lt;/p&gt;</p><p><br></p><p>&lt;h3&gt;سرکاری فیس شیڈول&lt;/h3&gt;</p><p>&lt;ul&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;پی ایل آر اے کے تازہ ترین جاری کردہ فیس شیڈول کے تحت گرین پراپرٹی سرٹیفکیٹ کی سرکاری فیس صرف &lt;strong&gt;800 روپے&lt;/strong&gt; رکھی گئی ہے۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;اگر کوئی ایجنٹ یا ایجنسی اس کام کے لیے ہزاروں روپے کا مطالبہ کرے تو یہ غلط ہے، کیونکہ یہ فیس ای-پے پنجاب (e-Pay Punjab) یا بینک آف پنجاب کے کاؤنٹر پر براہِ راست ادا کی جا سکتی ہے۔&lt;/li&gt;</p><p>&lt;/ul&gt;</p><p><br></p><p>&lt;h3&gt;گرین سرٹیفکیٹ حاصل کرنے کا مکمل طریقہ کار&lt;/h3&gt;</p><p>&lt;ol&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;&lt;strong&gt;اراضی سنٹر پر درخواست:&lt;/strong&gt; متعلقہ تحصیل کے اراضی ریکارڈ سنٹر یا متعلقہ پٹواری (ARC) پر اصل شناختی کارڈ کے ساتھ گرین سرٹیفکیٹ کی درخواست جمع کروائیں۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;&lt;strong&gt;پڑوسیوں کی تصدیق (Neighbour Verification):&lt;/strong&gt; سسٹم میں رجسٹرڈ زمین کے دائیں بائیں موجود دو ہمسایہ مالکان پورٹل پر تصدیق کریں گے کہ درخواست گزار ہی اس پلاٹ پر قابض ہے۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;&lt;strong&gt;پٹواری و ریونیو افسر موقع وزٹ:&lt;/strong&gt; مجاز ریونیو فیلڈ اسٹاف موقع پر جا کر زمین کی پیمائش اور حدود کی تصدیق کرے گا۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;&lt;strong&gt;15 دن کا عوامی اشتہار (Public Notice):&lt;/strong&gt; پی ایل آر اے کی ویب سائٹ پر 15 دن کے لیے پبلک نوٹس جاری کیا جاتا ہے تاکہ اگر کسی کا کوئی عذر یا دعویٰ ہو تو وہ سامنے لا سکے۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;&lt;strong&gt;سرٹیفکیٹ کا باضابطہ اجراء:&lt;/strong&gt; اگر 15 دن میں کوئی اعتراض موصول نہ ہو، تو اسسٹنٹ ڈائریکٹر لینڈ ریکارڈز (ADLR) پراپرٹی کو \'Green Status\' دے کر بارکوڈ والا سرٹیفکیٹ جاری کر دیتا ہے۔&lt;/li&gt;</p><p>&lt;/ol&gt;</p><p><br></p><p>&lt;p&gt;&lt;em&gt;سرمایہ کاروں کے لیے مشورہ: اگر بیچنے والے کے پاس گرین پراپرٹی سرٹیفکیٹ موجود ہے تو سمجھ لیں کہ اس پلاٹ کا ٹائٹل اور قبضہ 100 فیصد قانونی تنازعات سے پاک ہے۔&lt;/em&gt;&lt;/p&gt;</p>',
  'Green Property Certificate, GPC, PLRA, Land Parcel Map, GPS Boundary, Khasra Verification, Punjab Land Records',
  '6',
  '102',
  '0',
  '0',
  'published',
  '2026-10-22 01:45:50',
  '2026-11-01 14:53:24'
)
