-- 8. punjab-property-transfer-system-pts-housing-societies-rules
INSERT INTO `posts` (`id`, `user_id`, `title`, `title_ur`, `slug`, `category`, `featured_image`, `summary`, `summary_ur`, `content`, `content_ur`, `tags`, `read_time`, `views_count`, `likes_count`, `is_featured`, `status`, `created_at`, `updated_at`) VALUES (
  8,
  COALESCE((SELECT u.`id` FROM `users` u WHERE u.`role` = 'admin' ORDER BY u.`id` LIMIT 1), (SELECT MIN(u2.`id`) FROM `users` u2)),
  'Punjab Property Transfer System: Linking Housing Society Files to Official Records',
  'پنجاب پراپرٹی ٹرانسفر سسٹم (PTS): ہاؤسنگ سوسائٹیز کی فائلوں کو سرکاری ریکارڈ سے منسلک کرنے کا نیا قانون',
  'punjab-property-transfer-system-pts-housing-societies-rules',
  'Investment Tips',
  'blog_images/1792597706_6ad8deca0cbd3.jpg',
  'What the PLRA property transfer system means for housing society plots and files, the published PLRA charges, and how to protect yourself as a buyer.',
  'نجی ہاؤسنگ سوسائٹیز کے لیے پی ایل آر اے کا نیا پراپرٹی ٹرانسفر سسٹم (PTS) کیا ہے؟ فائل ٹرانسفر پر 3,000 روپے سرکاری فیس کا نفاذ اور سوسائٹی فائلوں کی کمپیوٹرائزیشن سے جعلی الاٹمنٹ کا خاتمہ۔',
  '<p>Fake files and several allotment letters for one plot have long been a risk in private housing schemes. PLRA now provides systems that link societies and development authorities to its records, which can make transfers easier to trace.</p>\n<h2>How it works</h2>\n<p>PLRA describes the property transfer process as submitting an application, giving buyer and seller details, paying fees by challan, completing biometric verification and receiving a transfer report. It also offers a <a href=\"https://hsms.punjab-zameen.gov.pk/\" rel=\"noopener\" target=\"_blank\">Housing Societies Management System (HSMS)</a> for approved societies.</p>\n<p>Both the buyer and seller must complete biometric verification at an Arazi Record Centre.</p>\n<h2>Published PLRA charges</h2>\n<p>The PLRA schedule for FY 2025-26 lists:</p>\n<ul>\n<li>Transfer of properties in cooperative societies and development authorities: Rs. 2,500</li>\n<li>HSMS transaction: Rs. 3,000 per transaction</li>\n<li>One-time onboarding by approved societies: Rs. 5,000 per property</li>\n</ul>\n<p>Charges are revised, so check the <a href=\"https://www.punjab-zameen.gov.pk/guidanceAndRegulation\" rel=\"noopener\" target=\"_blank\">latest PLRA notifications</a>.</p>\n<h2>How this helps buyers</h2>\n<ul>\n<li>Transfers go through an official process with biometric checks, not just a society register.</li>\n<li>There is an official record to refer to if a dispute arises.</li>\n</ul>\n<p>No system removes every risk, so a society being on a system does not by itself prove that a particular file is genuine.</p>\n<h2>Before you buy a file</h2>\n<ol>\n<li>Check the <a href=\"https://www.punjab-zameen.gov.pk/approvedSocieties\" rel=\"noopener\" target=\"_blank\">official PLRA society list</a>.</li>\n<li>Confirm the NOC and layout plan with the TMA or development authority.</li>\n<li>Ask the society to confirm the allotment in writing.</li>\n<li>Follow our <a href=\"https://www.assanzameen.com/blog/plot-khareedne-se-pehle-sarkari-checks-punjab\">6 official checks before buying a plot</a>.</li>\n</ol>\n<h2>More help</h2>\n<p>Open our <a href=\"https://www.assanzameen.com/tools/government-links\">Government Links Guide</a> to see all the official portals in one place. To contact PLRA or make a complaint, call <strong>(042) 111-22-22-77</strong> (Monday to Saturday, 8:00 AM to 5:00 PM).</p>\n<blockquote>This article was written on 1 November 2026 from information on the PLRA website. Assan Zameen is not a government body. Fees and procedures can change, so confirm with the relevant office before paying. This is not legal advice.</blockquote>',
  '<p>&lt;h2&gt;پنجاب پراپرٹی ٹرانسفر سسٹم (PTS): ہاؤسنگ اسکیموں میں فائل فراڈ کا مستقل خاتمہ&lt;/h2&gt;</p><p><br></p><p>&lt;p&gt;پنجاب حکومت اور پنجاب لینڈ ریکارڈز اتھارٹی (PLRA) نے نجی ہاؤسنگ سوسائٹیز میں چلنے والی فائلوں اور الاٹمنٹ کے نظام کو کنٹرول کرنے کے لیے &lt;strong&gt;پراپرٹی ٹرانسفر سسٹم (Property Transfer System - PTS)&lt;/strong&gt; نافذ کر دیا ہے۔ ماضی میں سوسائٹیز کے دفاتر بغیر کسی سرکاری مانیٹرنگ کے ہزاروں فرضی فائلیں چھاپ کر فروخت کر دیتے تھے اور ایک ہی پلاٹ پر کئی کئی الاٹمنٹ لیٹرز جاری کر دیے جاتے تھے۔ پی ٹی ایس سسٹم کے بعد اب سوسائٹی کا ہر پلاٹ سرکاری ڈیٹا بیس سے منسلک ہو جائے گا۔&lt;/p&gt;</p><p><br></p><p>&lt;h3&gt;پی ٹی ایس سسٹم کیسے کام کرتا ہے؟&lt;/h3&gt;</p><p>&lt;p&gt;اس سسٹم کے تحت ڈویلپمنٹ اتھارٹیز (جیسے ایل ڈی اے، ایف ڈی اے، آر ڈی اے) اور نجی ہاؤسنگ سوسائٹیز کو پی ایل آر اے کے مرکزی سرور کے ساتھ منسلک کیا جا رہا ہے۔ جب بھی کوئی شہری کسی سوسائٹی میں پلاٹ کی فائل خریدے گا یا کسی دوسرے گاہک کو ٹرانسفر کروائے گا، تو اس کا اندراج صرف سوسائٹی کے کچے رجسٹر میں نہیں ہو گا، بلکہ پی ٹی ایس پورٹل کے ذریعے براہِ راست سرکاری ریونیو ریکارڈ میں اپ ڈیٹ ہو گا۔&lt;/p&gt;</p><p><br></p><p>&lt;h3&gt;سرکاری فیس اور چالان&lt;/h3&gt;</p><p>&lt;ul&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;نوٹیفکیشن کے تحت سوسائٹیز میں فائل ٹرانسفر پر پی ٹی ایس کی سرکاری فیس &lt;strong&gt;3,000 روپے فی ٹرانزیکشن&lt;/strong&gt; مقرر کی گئی ہے۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;یہ فیس ادا کرنے کے بعد الاٹمنٹ لیٹر پر ایک محفوظ بارکوڈ پرنٹ ہو گا جسے کوئی بھی شہری اپنے موبائل سے اسکین کر کے تصدیق کر سکے گا کہ فائل اصل ہے یا جعلی۔&lt;/li&gt;</p><p>&lt;/ul&gt;</p><p><br></p><p>&lt;h3&gt;خریداروں اور سرمایہ کاروں کو کیا فائدہ ہو گا؟&lt;/h3&gt;</p><p>&lt;ol&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;&lt;strong&gt;اوور سیلنگ کا خاتمہ:&lt;/strong&gt; سوسائٹی کا مالک اب اپنے پاس موجود رقبے سے ایک انچ بھی زیادہ پلاٹ نہیں بیچ سکے گا، کیونکہ سسٹم میں اضافی فائل رجسٹر ہی نہیں ہو گی۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;&lt;strong&gt;پراپرٹی ٹیکس اور فائلر بینیفٹ:&lt;/strong&gt; خریدار کے ٹیکس گوشوارے میں پلاٹ کی فائل کا باضابطہ نمبر ظاہر ہو گا جس سے خریدار کو قانونی تحفظ حاصل رہے گا۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;&lt;strong&gt;فائل گم ہونے کا ڈر ختم:&lt;/strong&gt; اگر اصل فائل گم ہو جائے تو سوسائٹی کا چکر کاٹنے کی ضرورت نہیں رہے گی کیونکہ پی ٹی ایس سرور میں خریدار کی بائیو میٹرک تصدیق سے ڈپلیکیٹ ریکارڈ چند منٹوں میں دستیاب ہو گا۔&lt;/li&gt;</p><p>&lt;/ol&gt;</p><p><br></p><p>&lt;p&gt;&lt;em&gt;اہم مشورہ: کسی بھی نجی سوسائٹی میں فائل خریدنے سے پہلے تسلی کریں کہ آیا سوسائٹی پی ٹی ایس سسٹم پر آن بورڈ ہے یا نہیں۔ محفوظ ترین حل کے لیے آسان زمین پر رجسٹرڈ تصدیق شدہ اسکیموں کا انتخاب کریں۔&lt;/em&gt;&lt;/p&gt;</p>',
  'PTS System, Housing Societies, Plot File Transfer, PLRA Punjab, Property Transfer System, Smart Allotment',
  '5',
  '28',
  '1',
  '0',
  'published',
  '2026-10-22 01:48:26',
  '2026-11-01 14:53:22'
)
