-- 9. punjab-e-registration-biometric-registry-dehi-markaz-maal-guide
INSERT INTO `posts` (`id`, `user_id`, `title`, `title_ur`, `slug`, `category`, `featured_image`, `summary`, `summary_ur`, `content`, `content_ur`, `tags`, `read_time`, `views_count`, `likes_count`, `is_featured`, `status`, `created_at`, `updated_at`) VALUES (
  9,
  COALESCE((SELECT u.`id` FROM `users` u WHERE u.`role` = 'admin' ORDER BY u.`id` LIMIT 1), (SELECT MIN(u2.`id`) FROM `users` u2)),
  'Punjab e-Registration: Online Registry, Biometric Verification and Auto Mutation',
  'پنجاب میں اب گھر بیٹھے بائیو میٹرک رجسٹری: ای-رجسٹریشن پورٹل اور دیہی مرکزِ مال کا نیا طریقہ کار',
  'punjab-e-registration-biometric-registry-dehi-markaz-maal-guide',
  'Property Guides',
  'blog_images/1792823881_6adc5249ba4b5.jpg',
  'How the Punjab e-Registration system works, from the online challan to Sub-Registrar statements, biometric checks and automatic mutation in online mouzas.',
  'سب رجسٹرار دفاتر کے چکروں سے نجات؛ پنجاب لینڈ ریکارڈز اتھارٹی کا نیا ای-رجسٹریشن پورٹل اور دیہی مرکزِ مال کے ذریعے بائیو میٹرک تصدیق سے رجسٹری اور فوری انتقال کروانے کی مکمل گائیڈ۔',
  '<p>PLRA and the Board of Revenue have moved property registration to a digital system, which reduces paperwork and improves record keeping for buyers and sellers.</p>\n<h2>How e-Registration works</h2>\n<ol>\n<li><strong>Online challan:</strong> create an <a href=\"https://www.assanzameen.com/blog/e-stamp-challan-32a-kaise-banayein-punjab-guide\">e-Stamp Challan 32-A</a> and pay stamp duty, FBR taxes, registration fee, mutation fee and other charges.</li>\n<li><strong>Portal login:</strong> create a user login on the <a href=\"https://eregistration.punjab-zameen.gov.pk/\" rel=\"noopener\" target=\"_blank\">e-Registration portal</a>.</li>\n<li><strong>Start the deed:</strong> begin the registration request in the system.</li>\n<li><strong>Enter the details:</strong> verify paid challans and enter the buyer, seller and witnesses.</li>\n<li><strong>Sub-Registrar:</strong> the request is forwarded, and statements of the parties and witnesses are recorded.</li>\n<li><strong>Issue:</strong> the registered document is issued with its Bahi number and document number.</li>\n</ol>\n<h2>Paying the charges</h2>\n<p>Challan amounts can be paid at any Bank of Punjab branch or online through PSID and banking apps.</p>\n<h2>Automatic mutation</h2>\n<p>According to PLRA, in online mouzas the mutation of an e-Registry is processed automatically, so the registry and mutation are approved together. The owner\'s name then changes in the record without a separate mutation visit.</p>\n<h2>Before you buy</h2>\n<p>Get a <a href=\"https://www.assanzameen.com/blog/fard-kaise-hasil-karein-punjab-online-arc-guide\">fresh fard</a> from an official source and verify its QR code. Buying land where the record is unclear can cost you dearly, so check this before paying. Assan Zameen does not verify ownership. Use the official PLRA services and a qualified lawyer.</p>\n<p>See our step by step <a href=\"https://www.assanzameen.com/blog/nayi-registry-ka-tareeqa-e-registration-punjab-steps\">new registry guide</a> for more detail.</p>\n<h2>More help</h2>\n<p>Open our <a href=\"https://www.assanzameen.com/tools/government-links\">Government Links Guide</a> to see all the official portals in one place. To contact PLRA or make a complaint, call <strong>(042) 111-22-22-77</strong> (Monday to Saturday, 8:00 AM to 5:00 PM).</p>\n<blockquote>This article was written on 1 November 2026 from information on the PLRA website. Assan Zameen is not a government body. Fees and procedures can change, so confirm with the relevant office before paying. This is not legal advice.</blockquote>',
  '<p>&lt;h2&gt;پنجاب میں ای-رجسٹریشن: روایتی رجسٹری کلچر کا خاتمہ اور آن لائن بیع نامہ&lt;/h2&gt;&lt;p&gt;پنجاب لینڈ ریکارڈز اتھارٹی (PLRA) اور بورڈ آف ریونیو نے جائیداد کی خرید و فروخت کو شفاف بنانے کے لیے &lt;strong&gt;ای-رجسٹریشن سسٹم (e-Registration Portal)&lt;/strong&gt; کو تمام اضلاع اور تحصیلوں میں لازمی قرار دے دیا ہے۔ اب خریدار اور فروخت کنندہ کو سفید یا اسٹامپ پیپر پر کاتب کے پاس جا کر ہاتھ سے دستاویزات تیار کروانے یا سب رجسٹرار کے عملے کی منتیں کرنے کی ضرورت نہیں رہی۔&lt;/p&gt;&lt;h3&gt;ای-رجسٹریشن پورٹل کے تحت رجسٹری کا مرحلہ وار طریقہ&lt;/h3&gt;&lt;ol&gt;</p><p><br></p><p>&nbsp;&lt;li&gt;&lt;strong&gt;آن لائن چالان جنریشن:&lt;/strong&gt; خریدار یا وکیل پی ایل آر اے کی ویب سائٹ پر جا کر زمین کی لوکیشن (ضلع، تحصیل، موضع اور خسرہ نمبر) درج کرتا ہے، جس کے بعد ایف بی آر ڈی سی ریٹ اور اسٹامپ ڈیوٹی کے تحت خودکار 32-A چالان بن جاتا ہے۔&lt;/li&gt;</p><p><br></p><p>&nbsp;&lt;li&gt;&lt;strong&gt;بینک یا ون بل (1-Bill) کے ذریعے ادائیگی:&lt;/strong&gt; تمام ٹیکسز (اسٹامپ ڈیوٹی، ٹی ایم اے، ایف بی آر ایڈوانس ٹیکس) ایزی پیسہ، جاز کیش یا بینک ایپ سے بغیر کسی رشوت کے جمع ہو جاتے ہیں۔&lt;/li&gt;</p><p><br></p><p>&nbsp;&lt;li&gt;&lt;strong&gt;ڈیجیٹل بیع نامہ اور وقت کا انتخاب (Appointment):&lt;/strong&gt; چالان ادا کرنے کے بعد سسٹم میں آن لائن بیع نامہ جنریٹ ہوتا ہے اور بائیو میٹرک کے لیے مرضی کا دن اور وقت منتخب کیا جاتا ہے۔&lt;/li&gt;&lt;/ol&gt;&lt;h3&gt;دیہی مرکزِ مال (DMM) اور سب رجسٹرار آفس میں بائیو میٹرک&lt;/h3&gt;&lt;p&gt;خریدار اور فروخت کنندہ مقررہ تاریخ پر قریبی &lt;strong&gt;دیہی مرکزِ مال&lt;/strong&gt; یا سب رجسٹرار آفس جاتے ہیں جہاں نادرا (NADRA) سے لائیو فنگر پرنٹ اور چہرے کی تصدیق کی جاتی ہے۔ بائیو میٹرک ہوتے ہی رجسٹری پر کیو آر (QR) کوڈ پرنٹ ہو جاتا ہے۔&lt;/p&gt;&lt;h3&gt;سب سے بڑا فائدہ: خودکار انتقال (Instant Auto-Mutation)&lt;/h3&gt;&lt;ul&gt;</p><p><br></p><p>&nbsp;&lt;li&gt;ای-رجسٹریشن کے تحت جیسے ہی سب رجسٹرار بٹن پریس کرتا ہے، رجسٹری کا ڈیٹا فوراً کمپیوٹرائزڈ اراضی سنٹر کے سسٹم میں ٹرانسفر ہو جاتا ہے اور &lt;strong&gt;خودکار انتقال (Automatic Mutation)&lt;/strong&gt; درج ہو کر نام تبدیل ہو جاتا ہے۔&lt;/li&gt;&lt;/ul&gt;&lt;p&gt;&lt;em&gt;سرمایہ کاروں کے لیے رہنمائی: بغیر کمپیوٹرائزڈ اراضی ریکارڈ کے پلاٹ خریدنا سنگین مالی نقصان کا باعث بن سکتا ہے۔ اپنے پلاٹ کی ملکیت اور سابقہ رجسٹری کی تصدیق آسان زمین پورٹل کے ذریعے کریں۔&lt;/em&gt;&lt;/p&gt;</p>',
  'E-Registration Punjab, Dehi Markaz Maal, Biometric Registry, PLRA Land Record, Online Intiqal, Sub Registrar Portal',
  '5',
  '20',
  '1',
  '0',
  'published',
  '2026-10-24 16:38:01',
  '2026-11-01 14:53:21'
)
ON DUPLICATE KEY UPDATE
  `title` = VALUES(`title`), `title_ur` = VALUES(`title_ur`), `summary` = VALUES(`summary`), `summary_ur` = VALUES(`summary_ur`), `content` = VALUES(`content`), `content_ur` = VALUES(`content_ur`),
