-- 10. non-filer-property-purchase-ban-fbr-section-7e-rules
INSERT INTO `posts` (`id`, `user_id`, `title`, `title_ur`, `slug`, `category`, `featured_image`, `summary`, `summary_ur`, `content`, `content_ur`, `tags`, `read_time`, `views_count`, `likes_count`, `is_featured`, `status`, `created_at`, `updated_at`) VALUES (
  10,
  COALESCE((SELECT u.`id` FROM `users` u WHERE u.`role` = 'admin' ORDER BY u.`id` LIMIT 1), (SELECT MIN(u2.`id`) FROM `users` u2)),
  'Non-Filers and Property in Pakistan: Higher Tax, Section 7E and Bank Payments',
  'نان فائلرز پر پلاٹ اور مکان کی خریداری پر مکمل پابندی: سیکشن 7E اور نقد ٹرانزیکشنز کے نئے قوانین',
  'non-filer-property-purchase-ban-fbr-section-7e-rules',
  'Taxes & Laws',
  'blog_images/1792824347_6adc541be03f6.jpg',
  'What non-filers should know before buying or selling property: higher 236-K and 236-C tax, section 7E and why you should pay through a bank.',
  'ایف بی آر کی طرف سے نان فائلرز کے لیے پراپرٹی خریدنے پر قانونی پابندیوں، کیش پر 50 لاکھ سے زائد لین دین پر پابندی اور انکم ٹیکس سیکشن 7E کے سرٹیفکیٹ کی لازمی شرط کی تفصیلی وضاحت۔',
  '<p>FBR has made property deals much more expensive for people who are not on the Active Taxpayers List. Before you buy or sell, understand what your status means.</p>\n<h2>Filers pay less</h2>\n<p>Two federal taxes apply to most sales:</p>\n<ul>\n<li><strong>Section 236-K:</strong> advance tax on the buyer.</li>\n<li><strong>Section 236-C:</strong> tax on the seller.</li>\n</ul>\n<p>Non-filers pay these at much higher rates than active filers. Rates change with the budget, so confirm the current ones with FBR or a tax adviser. Our <a href=\"https://www.assanzameen.com/tools/registry-tax-calculator\">Registry & Tax Calculator</a> gives an estimate.</p>\n<h2>Check your status</h2>\n<p>Look up your CNIC on the <a href=\"https://e.fbr.gov.pk/atl/\" rel=\"noopener\" target=\"_blank\">FBR Active Taxpayers List</a>. To become a filer, submit your return through the <a href=\"https://iris.fbr.gov.pk/\" rel=\"noopener\" target=\"_blank\">FBR IRIS portal</a>.</p>\n<h2>What is section 7E?</h2>\n<p>Section 7E of the Income Tax Ordinance deals with tax on deemed income from certain immovable property, with exemptions in some cases. A seller may be asked for a certificate from FBR showing the tax is paid or an exemption applies. Check with a tax adviser well before your sale, as a missing certificate can delay the transfer.</p>\n<h2>Pay through a bank</h2>\n<p>Income tax law restricts large cash payments for immovable property. Whatever the amount, a bank payment such as a pay order, demand draft or crossed cheque gives you a clear record, while large cash deals can bring questions from the tax department. Attach the payment record to your agreement.</p>\n<h2>Our advice</h2>\n<p>If you plan to buy, consider becoming a filer first, because the tax saved on one deal can be significant. Ask a qualified tax adviser about your own case.</p>\n<h2>More help</h2>\n<p>Open our <a href=\"https://www.assanzameen.com/tools/government-links\">Government Links Guide</a> to see all the official portals in one place. To contact PLRA or make a complaint, call <strong>(042) 111-22-22-77</strong> (Monday to Saturday, 8:00 AM to 5:00 PM).</p>\n<blockquote>This article was written on 1 November 2026 from information on the PLRA website. Assan Zameen is not a government body. Fees and procedures can change, so confirm with the relevant office before paying. This is not legal advice.</blockquote>',
  '<p>&lt;h2&gt;نان فائلرز کے لیے جائیداد کی خرید و فروخت: نئے ایف بی آر قوانین اور سزائیں&lt;/h2&gt;&lt;p&gt;فیڈرل بورڈ آف ریونیو (FBR) نے رئیل اسٹیٹ میں غیر دستاویزی معیشت کو روکنے کے لیے نان فائلرز پر گھیرا مزید تنگ کر دیا ہے۔ نئے قانونی اقدامات کے تحت نان فائلرز کے لیے نہ صرف پراپرٹی خریدنے پر بھاری ٹیکس سلیب اور سزائیں عائد کی گئی ہیں بلکہ مخصوص حد سے زائد جائیداد کی ٹرانسفر پر مکمل پابندیوں کا فریم ورک بھی نافذ کیا گیا ہے۔&lt;/p&gt;&lt;h3&gt;سیکشن 7E سرٹیفکیٹ کی شرط کیا ہے؟&lt;/h3&gt;&lt;p&gt;انکم ٹیکس آرڈیننس کے &lt;strong&gt;سیکشن 7E&lt;/strong&gt; کے تحت، جب بھی کوئی شہری کوئی مکان، زرعی زمین، کمرشل عمارت یا پلاٹ فروخت کرتا ہے یا ٹرانسفر کرواتا ہے، تو سب رجسٹرار یا سوسائٹی انتظامیہ کے لیے لازم ہے کہ وہ فروخت کنندہ سے &lt;em&gt;ایف بی آر کا 7E ایگزیمپشن سرٹیفکیٹ&lt;/em&gt; طلب کرے۔ اگر آپ کی کل جائیدادیں اڑھائی کروڑ روپے سے کم ہیں تو بھی سسٹم سے آن لائن استثنیٰ کا سرٹیفکیٹ حاصل کرنا لازمی ہے۔&lt;/p&gt;&lt;h3&gt;نان فائلرز اور فائلرز کے ٹیکسز کا واضح موازنہ&lt;/h3&gt;&lt;ul&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;&lt;strong&gt;سیکشن 236-K (خریدار کا ایڈوانس ٹیکس):&lt;/strong&gt; ایکٹو ٹیکس پیئر (فائلر) کے لیے یہ ٹیکس پراپرٹی کی قیمت کا &lt;strong&gt;3%&lt;/strong&gt; ہے، جبکہ نان فائلر کے لیے یہ شرح بڑھ کر &lt;strong&gt;10.5% سے 12%&lt;/strong&gt; تک پہنچ جاتی ہے۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;&lt;strong&gt;سیکشن 236-C (فروخت کنندہ کا ٹیکس):&lt;/strong&gt; فائلر کے لیے 3% مقرر ہے جبکہ نان فائلر کو فروخت کرتے وقت 10% تک ادا کرنا پڑتا ہے۔&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;کیش (Cash) میں سودا کرنے پر سخت پابندی&lt;/h3&gt;&lt;ol&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;اب کچہری یا سوسائٹی کے دفتر میں نوٹوں کے تھیلوں کے ساتھ پراپرٹی کا سودا قانونی نہیں مانا جاتا۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;قانون کے مطابق پلاٹ کی پوری قیمت صرف &lt;strong&gt;بینکنگ چینل (پے آرڈر، ڈیمانڈ ڈرافٹ یا کراس چیک)&lt;/strong&gt; کے ذریعے ادا ہونی چاہیے۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;اگر کیش کے ذریعے ادائیگی ثابت ہو تو اس لین دین کو مشکوک قرار دے کر ٹیکس ڈپارٹمنٹ کی طرف سے نوٹس جاری ہو سکتا ہے۔&lt;/li&gt;&lt;/ol&gt;&lt;p&gt;&lt;em&gt;قانونی تجویز: جائیداد خریدنے سے پہلے اپنا نام ایف بی آر کی ایکٹو ٹیکس پیئر لسٹ (ATL) میں شامل کروائیں تاکہ آپ لاکھوں روپے کے اضافی سرکاری چالان سے بچ سکیں۔ مستند ریٹس اور قانونی رہنمائی کے لیے آسان زمین کے پورٹل سے جڑے رہیں۔&lt;/em&gt;&lt;/p&gt;</p>',
  'Non Filer Property Ban, Section 7E FBR, Property Purchase Tax, Real Estate Tax Pakistan, Advance Tax 236K, FBR Active Taxpayer',
  '6',
  '14',
  '0',
  '0',
  'published',
  '2026-10-24 16:45:47',
  '2026-11-01 14:53:19'
)
