-- 11. dc-rate-vs-fbr-rate-market-value-difference-punjab
INSERT INTO `posts` (`id`, `user_id`, `title`, `title_ur`, `slug`, `category`, `featured_image`, `summary`, `summary_ur`, `content`, `content_ur`, `tags`, `read_time`, `views_count`, `likes_count`, `is_featured`, `status`, `created_at`, `updated_at`) VALUES (
  11,
  COALESCE((SELECT u.`id` FROM `users` u WHERE u.`role` = 'admin' ORDER BY u.`id` LIMIT 1), (SELECT MIN(u2.`id`) FROM `users` u2)),
  'DC Rate vs FBR Value vs Market Rate: What Is the Difference in Punjab?',
  'ڈی سی ریٹ، ایف بی آر ویلیو اور مارکیٹ ریٹ میں کیا فرق ہے؟ پلاٹ کی سرکاری قیمت نکالنے کا فارمولا',
  'dc-rate-vs-fbr-rate-market-value-difference-punjab',
  'Market News',
  'blog_images/1792824637_6adc553d7b84c.jpg',
  'The three property values used in Pakistan: DC rate, FBR valuation and market price. Learn which one affects stamp duty and federal tax.',
  'پلاٹ یا مکان خریدتے وقت ڈی سی ریٹ اور ایف بی آر ریٹ کا فرق سمجھیں؛ اسٹامپ ڈیوٹی، وفاقی انکم ٹیکس اور کچہری چالان کس ریٹ پر لاگو ہوتے ہیں اور ان کی آن لائن جانچ کا طریقہ۔',
  '<p>A buyer often agrees a price of 50 lakh, then sees a different figure on the registry challan. That is because three different values are used in a property deal.</p>\n<h2>1. DC rate</h2>\n<p>This is the official value notified by the District Collector, and it varies by location, land type and category. PLRA says it is the basis for stamp duty, registration fees and other government charges. You can <a href=\"https://www.assanzameen.com/blog/dc-valuation-kaise-check-karein-punjab\">check the DC rate online</a>.</p>\n<h2>2. FBR valuation</h2>\n<p>FBR publishes its own valuation tables for many cities and housing schemes. They are used for federal income tax on property, such as section 236-C on the seller and section 236-K on the buyer. Confirm with FBR or a tax adviser how the value applies to your deal.</p>\n<h2>3. Market rate</h2>\n<p>This is the price the buyer actually pays the seller. It depends on demand, road width, commercial value and development, and it is often higher than the official values.</p>\n<h2>The rule that matters: the higher value</h2>\n<p>PLRA\'s e-Stamp guidance says stamp duty is calculated on the <strong>declared value or the DC valuation, whichever is higher</strong>. So a low declared price will not reduce the duty, and a declared price above the DC rate means duty on the declared price.</p>\n<h2>A simple example</h2>\n<table>\n<thead><tr><th>Value of a 5 marla house</th><th>Amount</th></tr></thead>\n<tbody>\n<tr><td>DC rate</td><td>Rs. 20 lakh</td></tr>\n<tr><td>FBR valuation</td><td>Rs. 28 lakh</td></tr>\n<tr><td>Agreed market price</td><td>Rs. 50 lakh</td></tr>\n</tbody>\n</table>\n<p>If you declare Rs. 50 lakh, the e-Stamp system charges stamp duty on Rs. 50 lakh, as it is higher than the DC rate. If you declared only Rs. 15 lakh, duty would still be charged on Rs. 20 lakh. These figures are examples only.</p>\n<p>The fastest way to see the real amount is to <a href=\"https://www.assanzameen.com/blog/e-stamp-challan-32a-kaise-banayein-punjab-guide\">create an e-Stamp challan</a>, because the system calculates it. Check the latest rates before you register, as a wrong value can cause an objection.</p>\n<h2>More help</h2>\n<p>Open our <a href=\"https://www.assanzameen.com/tools/government-links\">Government Links Guide</a> to see all the official portals in one place. To contact PLRA or make a complaint, call <strong>(042) 111-22-22-77</strong> (Monday to Saturday, 8:00 AM to 5:00 PM).</p>\n<blockquote>This article was written on 1 November 2026 from information on the PLRA website. Assan Zameen is not a government body. Fees and procedures can change, so confirm with the relevant office before paying. This is not legal advice.</blockquote>',
  '<p>&lt;h2&gt;ڈی سی ریٹ، ایف بی آر ریٹ اور مارکیٹ ویلیو: خریداروں کے لیے مکمل حسابی گائیڈ&lt;/h2&gt;&lt;p&gt;پاکستان میں جب بھی کوئی پلاٹ، مکان یا زرعی رقبہ خریدا جاتا ہے تو اکثر خریدار اس کشمکش میں مبتلا ہو جاتے ہیں کہ ڈیل 50 لاکھ میں ہوئی ہے لیکن پٹواری یا وکیل رجسٹری کے چالان پر کچھ اور رقم لکھ رہا ہے۔ رئیل اسٹیٹ ٹرانزیکشن میں تین قسم کی قیمتیں استعمال ہوتی ہیں جن کا فرق سمجھنا ہر سرمایہ کار کے لیے ضروری ہے۔&lt;/p&gt;&lt;h3&gt;1. ڈی سی ریٹ (Deputy Commissioner Rate) کیا ہے؟&lt;/h3&gt;&lt;p&gt;ڈی سی ریٹ ہر ضلع کا ڈپٹی کمشنر اور صوبائی بورڈ آف ریونیو سالانہ بنیادوں پر جاری کرتا ہے۔ یہ وہ کم از کم سرکاری ریٹ ہے جس سے نیچے آپ کی رجسٹری رجسٹرار آفس میں درج نہیں ہو سکتی۔&lt;/p&gt;&lt;ul&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;&lt;strong&gt;کون سے ٹیکس لاگو ہوتے ہیں؟&lt;/strong&gt; پنجاب میں اسٹامپ ڈیوٹی (Stamp Duty)، ٹی ایم اے (TMA/لوکل کونسل فیس) اور پی ایل آر اے رجسٹریشن فیس ہمیشہ &lt;strong&gt;ڈی سی ریٹ&lt;/strong&gt; پر شمار کی جاتی ہے۔&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;2. ایف بی آر ریٹ (FBR Valuation Table) کیا ہے؟&lt;/h3&gt;&lt;p&gt;فیڈرل بورڈ آف ریونیو (FBR) پاکستان کے بڑے شہروں اور سوسائٹیز کے لیے الگ سے ویلیوایشن ٹیبل جاری کرتا ہے، جو عام طور پر صوبائی ڈی سی ریٹ سے قدرے زیادہ ہوتا ہے۔&lt;/p&gt;&lt;ul&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;&lt;strong&gt;کون سے ٹیکس لاگو ہوتے ہیں؟&lt;/strong&gt; وفاقی ایڈوانس انکم ٹیکس یعنی سیکشن 236-C (سیلر کا ٹیکس) اور سیکشن 236-K (خریدار کا ٹیکس) ہمیشہ &lt;strong&gt;ایف بی آر ریٹ&lt;/strong&gt; یا ڈیکلیرڈ ویلیو (جو بھی زیادہ ہو) پر لاگو ہوتے ہیں۔&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;3. مارکیٹ ریٹ (Actual Market Value)&lt;/h3&gt;&lt;p&gt;مارکیٹ ریٹ وہ اصل رقم ہے جو خریدار سیلر کو بینکنگ چینل (پے آرڈر) کے ذریعے ادا کرتا ہے۔ یہ ریٹ علاقے کی ڈیمانڈ، سڑک کی چوڑائی، کمرشل ویلیو اور ڈیولپمنٹ کی بنیاد پر ڈی سی اور ایف بی آر دونوں ریٹس سے زیادہ ہوتا ہے۔&lt;/p&gt;&lt;h3&gt;پراپرٹی چالان کا عملی حساب (مثال)&lt;/h3&gt;&lt;ol&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;اگر ایک 5 مرلہ مکان کا ڈی سی ریٹ 20 لاکھ روپے مقرر ہے۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;اسی مکان کا ایف بی آر ویلیوایشن ریٹ 28 لاکھ روپے ہے۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;اور آپ نے وہ مکان مارکیٹ میں 50 لاکھ روپے کا خریدا ہے۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;تو کچہری میں اسٹامپ ڈیوٹی 20 لاکھ (ڈی سی ریٹ) پر لگے گی، جبکہ انکم ٹیکس فائلر کا 3% چالان 28 لاکھ (ایف بی آر ریٹ) پر ادا کیا جائے گا۔&lt;/li&gt;&lt;/ol&gt;&lt;p&gt;&lt;em&gt;اہم مشورہ: رجسٹری بنوانے سے پہلے اپنی متعلقہ تحصیل کا تازہ ترین ڈی سی اور ایف بی آر ٹیبل ضرور چیک کریں۔ غلط ویلیوایشن کی وجہ سے سب رجسٹرار آفس میں فائل پر اعتراض لگ سکتا ہے۔&lt;/em&gt;&lt;/p&gt;</p>',
  'DC Rate Punjab, FBR Property Valuation, Market Value, Stamp Duty Valuation, Advance Tax Calculation, Property Evaluation',
  '5',
  '15',
  '0',
  '0',
  'published',
  '2026-10-24 16:50:37',
  '2026-11-01 14:53:18'
)
