-- 12. succession-certificate-inheritance-intiqal-guide-punjab
INSERT INTO `posts` (`id`, `user_id`, `title`, `title_ur`, `slug`, `category`, `featured_image`, `summary`, `summary_ur`, `content`, `content_ur`, `tags`, `read_time`, `views_count`, `likes_count`, `is_featured`, `status`, `created_at`, `updated_at`) VALUES (
  12,
  COALESCE((SELECT u.`id` FROM `users` u WHERE u.`role` = 'admin' ORDER BY u.`id` LIMIT 1), (SELECT MIN(u2.`id`) FROM `users` u2)),
  'Inherited Property in Punjab: Succession Certificate, Family Tree and Mutation',
  'وراثتی جائیداد کی تقسیم اور انتقال کا طریقہ: نادرا جانشینی سرٹیفکیٹ اور پٹواری شجرہ نسب',
  'succession-certificate-inheritance-intiqal-guide-punjab',
  'Property Guides',
  'blog_images/1792825093_6adc57052ba1f.jpg',
  'How heirs can transfer inherited property in Punjab: death certificate, FRC, NADRA succession certificate, family tree verification and inheritance mutation.',
  'والد یا مورث کے انتقال کے بعد وراثتی جائیداد اپنے نام منتقل کروانے کا مکمل طریقہ کار؛ نادرا سکسیشن سرٹیفکیٹ، پٹواری سے شجرہ نسب کی تصدیق اور اراضی ریکارڈ سنٹر میں انتقال کی تفصیل۔',
  '<p>Transferring a family member\'s property to the heirs used to mean years in court. Today there are simpler routes through NADRA and the Arazi Record Centres, but you still need the right papers in the right order.</p>\n<h2>Step 1: Death certificate and FRC</h2>\n<ul>\n<li>Get the computerized death certificate from the Union Council.</li>\n<li>Get a Family Registration Certificate (FRC) from NADRA showing the legal heirs.</li>\n</ul>\n<h2>Step 2: Succession certificate, where needed</h2>\n<p>NADRA also issues succession certificates and letters of administration through its Succession Facilitation Units, so many families can avoid a court application. Generally all heirs complete biometric verification, a public notice is given so that any other heir can come forward, and the certificate is issued if nobody objects. Check the current requirements and time at NADRA, and ask the Arazi Record Centre whether your case needs this certificate.</p>\n<h2>Step 3: Inheritance mutation</h2>\n<p>According to PLRA, any legal heir can approach an Arazi Record Centre with:</p>\n<ul>\n<li>Death certificate</li>\n<li>FRC form</li>\n<li>Affidavit</li>\n<li>Property details</li>\n<li>CNIC copies of all legal heirs</li>\n</ul>\n<p>The file goes to field staff for shajra nasab (family tree) verification, and after the report the inheritance mutation is attested at the centre. Read our full <a href=\"https://www.assanzameen.com/blog/wirasati-intiqal-ka-tareeqa-punjab-kaghzat\">inheritance mutation guide</a>.</p>\n<h2>Protect the rights of every heir</h2>\n<p>Daughters, widows and other heirs have a legal share. Leaving a woman out of a mutation or hiding her name is against the law and can be challenged. If an inheritance mutation is wrongly approved, PLRA says you can appeal to the Assistant Commissioner or go to the civil court.</p>\n<p>Our free <a href=\"https://www.assanzameen.com/tools/inheritance-calculator\">Inheritance Calculator</a> gives an estimate of the shares. Please confirm with a scholar or lawyer.</p>\n<h2>More help</h2>\n<p>Open our <a href=\"https://www.assanzameen.com/tools/government-links\">Government Links Guide</a> to see all the official portals in one place. To contact PLRA or make a complaint, call <strong>(042) 111-22-22-77</strong> (Monday to Saturday, 8:00 AM to 5:00 PM).</p>\n<blockquote>This article was written on 1 November 2026 from information on the PLRA website. Assan Zameen is not a government body. Fees and procedures can change, so confirm with the relevant office before paying. This is not legal advice.</blockquote>',
  '<p>&lt;h2&gt;وراثتی جائیداد کی تقسیم اور منتقلی: عدالتی چکروں کے بغیر آسان طریقہ&lt;/h2&gt;&lt;p&gt;ماضی میں سربراہِ خاندان کے انتقال کے بعد وراثتی جائیداد کو وارثان کے نام ٹرانسفر کروانا ایک مشکل اور طویل ترین عمل سمجھا جاتا تھا۔ سول کورٹس میں سالہا سال کیس چلتے رہتے تھے، تاہم حکومتِ پنجاب اور نادرا کے نئے قوانین کے بعد اب &lt;strong&gt;وراثتی انتقال (Inheritance Mutation)&lt;/strong&gt; صرف چند ہفتوں میں مکمل ہو جاتا ہے۔&lt;/p&gt;&lt;h3&gt;مرحلہ 1: نادرا سے ڈیتھ سرٹیفکیٹ اور فیملی رجسٹریشن (FRC)&lt;/h3&gt;&lt;ol&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;مرحوم کا یونین کونسل سے جاری شدہ کمپیوٹرائزڈ ڈیتھ سرٹیفکیٹ حاصل کریں۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;نادرا سینٹر سے مرحوم کے تمام شرعی وارثان پر مشتمل &lt;strong&gt;FRC (Family Registration Certificate)&lt;/strong&gt; بنوائیں۔&lt;/li&gt;&lt;/ol&gt;&lt;h3&gt;مرحلہ 2: نادرا جانشینی سرٹیفکیٹ (Succession Certificate)&lt;/h3&gt;&lt;p&gt;غیر منقولہ جائیداد (پلاٹ، مکان، زرعی رقبہ) اور بینک اکاؤنٹس کے لیے اب عدالت جانے کی بجائے نادرا کے کاؤنٹر سے 15 دنوں کے اندر سکسیشن سرٹیفکیٹ اور لیٹر آف ایڈمنسٹریشن جاری کر دیا جاتا ہے:&lt;/p&gt;&lt;ul&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;تمام وارثان کی نادرا دفتر میں بائیو میٹرک تصدیق ہوتی ہے۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;نادرا اخبار میں 14 دن کا عوامی اشتہار دیتا ہے تاکہ اگر کوئی دیگر وارث موجود ہو تو سامنے آ سکے۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;کوئی اعتراض نہ آنے پر نادرا بارکوڈ والا تصدیق شدہ جانشینی سرٹیفکیٹ جاری کر دیتا ہے۔&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;مرحلہ 3: پٹواری سے شجرہ نسب اور اراضی سنٹر میں انتقال&lt;/h3&gt;&lt;ol&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;حلقہ پٹواری نادرا ریکارڈ اور گاؤں/محلے کے معززین کی تصدیق سے &lt;strong&gt;شجرہ نسب (Family Tree)&lt;/strong&gt; مرتب کرتا ہے جس میں تمام بیٹوں، بیٹیوں اور بیوہ کا شرعی حصہ واضح لکھا جاتا ہے۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;یہ دستاویز لے کر قریبی &lt;strong&gt;اراضی ریکارڈ سنٹر (ARC)&lt;/strong&gt; یا دیہی مرکزِ مال میں پیش کی جاتی ہے۔&lt;/li&gt;</p><p>&nbsp;&nbsp;&lt;li&gt;ریونیو افسر تمام ورثا کی موقع پر تصدیق کے بعد وراثتی انتقال کی منظوری دیتا ہے اور ہر وارث کے نام الگ فرد جاری کر دی جاتی ہے۔&lt;/li&gt;&lt;/ol&gt;&lt;p&gt;&lt;em&gt;قانونی نکتہ: خواتین کے شرعی وراثتی حق کو غصب کرنا یا ان کا نام ظاہر کیے بغیر تنہا انتقال کروانا قانوناً سنگین جرم ہے جس پر سخت سزائیں مقرر ہیں۔ جائیداد کے قانونی ورثا کی شفاف جانچ کے لیے آسان زمین کا ڈیٹا بیس وزٹ کریں۔&lt;/em&gt;&lt;/p&gt;</p>',
  'Succession Certificate NADRA, Warasti Intiqal, Shajra Nasab Patwari, Inheritance Law Pakistan, Property Distribution, Arazi Record Center',
  '6',
