-- 13. fard-kaise-hasil-karein-punjab-online-arc-guide
INSERT INTO `posts` (`id`, `user_id`, `title`, `title_ur`, `slug`, `category`, `featured_image`, `summary`, `summary_ur`, `content`, `content_ur`, `tags`, `read_time`, `views_count`, `likes_count`, `is_featured`, `status`, `created_at`, `updated_at`) VALUES (
  NULL,
  COALESCE((SELECT u.`id` FROM `users` u WHERE u.`role` = 'admin' ORDER BY u.`id` LIMIT 1), (SELECT MIN(u2.`id`) FROM `users` u2)),
  'How to Get a Fard in Punjab: Online and Arazi Record Centre Guide',
  'فرد کیسے حاصل کریں؟ پنجاب میں آن لائن اور اراضی ریکارڈ سینٹر سے فرد لینے کا آسان طریقہ',
  'fard-kaise-hasil-karein-punjab-online-arc-guide',
  'Property Guides',
  NULL,
  'Three ways to get a fard in Punjab, the documents you need, the fee, sale fard rules and what to do if a fard is lost. Based on PLRA information.',
  'پنجاب میں فرد لینے کے تین طریقے، ضروری کاغذات، فیس، فرد برائے بیع اور گم شدہ فرد کا حل۔ PLRA کی معلومات پر مبنی آسان اردو گائیڈ۔',
  '<p>Whether you are buying land, selling it or simply checking ownership, the first thing you need is a <strong>fard</strong>. This guide explains what a fard is, where to get it and what to bring.</p>\n<h2>What is a fard?</h2>\n<p>A fard is an official document showing a piece of land\'s area, location and owner details. It is used as proof of ownership for a sale, court cases, loans and verification.</p>\n<h2>Three ways to get a fard</h2>\n<ol>\n<li><strong>Arazi Record Centre (ARC):</strong> visit the nearest centre, complete biometric verification and collect a printed fard.</li>\n<li><strong>Online:</strong> log in to the <a href=\"https://onlinefard.punjab-zameen.gov.pk/\" rel=\"noopener\" target=\"_blank\">PLRA online fard portal</a> and verify the details.</li>\n<li><strong>Arazi Moawin:</strong> get it from an Arazi Moawin centre in your area.</li>\n</ol>\n<p>You can also get one from a Dahi Markaz Mall where a patwari is available.</p>\n<h2>What to bring</h2>\n<ul>\n<li>Your original CNIC</li>\n<li>Property details such as khewat, khasra or registry</li>\n<li>For a first fard: the registry for urban property, or mutation details for rural land</li>\n</ul>\n<p>If you do not have the property details, you will be asked some verification questions before the fard is issued.</p>\n<h2>How much does a fard cost?</h2>\n<p>A fard is not free. According to PLRA, the fee is normally <strong>Rs. 50 per khatooni</strong>, up to <strong>Rs. 150 per khewat</strong>, plus PLRA service charges. You can also pay online.</p>\n<h2>Information fard and sale fard</h2>\n<ul>\n<li><strong>Information fard:</strong> for verification only.</li>\n<li><strong>Sale fard:</strong> used for a registry and transfer of ownership. The buyer\'s name and CNIC are mandatory, because this data goes directly to the e-Registry system.</li>\n</ul>\n<h2>Can someone else get my fard?</h2>\n<p>Yes, with a Mukhtarnama Aam (power of attorney) verified by the Sub-Registrar. To get a relative\'s fard, you also submit a verified copy of the mukhtarnama and an affidavit confirming the owner is alive.</p>\n<h2>How to check if a fard is genuine</h2>\n<p>Every fard has a printed QR code. Scan it to verify the document.</p>\n<h2>Common problems</h2>\n<h3>My fard is lost</h3>\n<p>Find your fard ID from the record centre or an old copy, then submit a police report and an affidavit. The old fard is cancelled and a new one is issued.</p>\n<h3>My fingerprints do not verify</h3>\n<p>First update your fingerprints at NADRA. If verification still fails because of old age, bring a co-owner or the village lumberdar so the Service Centre Incharge can issue a manual verification token.</p>\n<h3>My name is not in the record</h3>\n<p>Visit the Arazi Record Centre with your original documents and request a correction.</p>\n<h2>Does a fard expire?</h2>\n<p>PLRA says a fard has no fixed time limit, but transfers and mutations can change the information. So <strong>always get a fresh fard before any deal</strong>, even if the seller shows you an older one.</p>\n<h2>More help</h2>\n<p>Open our <a href=\"https://www.assanzameen.com/tools/government-links\">Government Links Guide</a> to see all the official portals in one place. To contact PLRA or make a complaint, call <strong>(042) 111-22-22-77</strong> (Monday to Saturday, 8:00 AM to 5:00 PM).</p>\n<blockquote>This article was written on 1 November 2026 from information on the PLRA website. Assan Zameen is not a government body. Fees and procedures can change, so confirm with the relevant office before paying. This is not legal advice.</blockquote>',
  '<p>زمین خریدنی ہو، بیچنی ہو یا صرف اپنی ملکیت چیک کرنی ہو، سب سے پہلے <strong>فرد</strong> کی ضرورت پڑتی ہے۔ اس مضمون میں ہم آسان الفاظ میں بتائیں گے کہ فرد کیا ہے، یہ کہاں سے ملتی ہے اور اس کے لیے کیا لے کر جانا ہے۔</p>\n<h2>فرد کیا ہوتی ہے؟</h2>\n<p>فرد ایک سرکاری دستاویز ہے جس میں زمین کا رقبہ، مقام اور مالک کی تفصیل درج ہوتی ہے۔ یہ بیع، عدالتی مقدمات، قرض اور تصدیق کے کاموں میں ملکیت کے ثبوت کے طور پر استعمال ہوتی ہے۔</p>\n<h2>فرد لینے کے تین طریقے</h2>\n<ol>\n<li><strong>اراضی ریکارڈ سینٹر (ARC):</strong> قریبی سینٹر جائیں، بائیو میٹرک تصدیق کروائیں اور پرنٹ شدہ فرد لیں۔</li>\n<li><strong>آن لائن:</strong> <a href=\"https://onlinefard.punjab-zameen.gov.pk/\" rel=\"noopener\" target=\"_blank\">PLRA کے آن لائن فرد پورٹل</a> پر لاگ اِن کر کے تفصیل کی تصدیق کریں۔</li>\n<li><strong>اراضی معاون:</strong> مختلف علاقوں میں قائم اراضی معاون مراکز سے بھی فرد مل سکتی ہے۔</li>\n</ol>\n<p>اس کے علاوہ جس دیہی مرکز مال میں پٹواری موجود ہو، وہاں سے بھی فرد لی جا سکتی ہے۔</p>\n<h2>کون سے کاغذات ساتھ لے جائیں؟</h2>\n<ul>\n<li>اصل شناختی کارڈ</li>\n<li>جائیداد کی تفصیل، جیسے کھیوٹ، خسرہ یا رجسٹری</li>\n<li>پہلی بار فرد لے رہے ہوں تو شہری جائیداد کے لیے رجسٹری اور دیہی زمین کے لیے انتقال کی تفصیل</li>\n</ul>\n<p>اگر آپ کے پاس جائیداد کی معلومات نہیں ہیں تو فرد جاری کرنے سے پہلے آپ سے تصدیق کے کچھ سوال پوچھے جائیں گے۔</p>\n<h2>فرد کی فیس کتنی ہے؟</h2>\n<p>فرد مفت نہیں ملتی۔ PLRA کے مطابق عام طور پر فیس <strong>50 روپے فی کھتونی</strong> اور زیادہ سے زیادہ <strong>150 روپے فی کھیوٹ</strong> ہوتی ہے، اور اس کے ساتھ PLRA کے سروس چارجز الگ لگتے ہیں۔ فیس آن لائن بھی ادا کی جا سکتی ہے۔</p>\n<h2>فرد برائے معلومات اور فرد برائے بیع میں فرق</h2>\n<ul>\n<li><strong>فرد برائے معلومات:</strong> صرف تصدیق کے لیے ہوتی ہے۔</li>\n<li><strong>فرد برائے بیع:</strong> رجسٹری اور ملکیت کی منتقلی کے لیے استعمال ہوتی ہے۔ اس میں خریدار کا نام اور شناختی کارڈ لازمی ہے، کیونکہ یہ معلومات خود بخود ای-رجسٹری سسٹم میں جاتی ہیں۔</li>\n</ul>\n<h2>کیا کوئی دوسرا میری فرد لے سکتا ہے؟</h2>\n<p>جی ہاں، اگر اس کے پاس سب رجسٹرار سے تصدیق شدہ مختار نامہ عام ہو۔ بھائی وغیرہ کی فرد لینے کے لیے مختار نامے کی تصدیق شدہ نقل اور یہ بیانِ حلفی بھی دینا ہوگا کہ مالک زندہ ہے۔</p>\n<h2>فرد اصلی ہے یا نقلی، کیسے پتا کریں؟</h2>\n<p>ہر فرد پر QR کوڈ چھپا ہوتا ہے۔ اسے اسکین کر کے فرد کی تصدیق کی جا سکتی ہے۔</p>\n<h2>عام مسائل اور ان کا حل</h2>\n<h3>فرد گم ہو جائے تو؟</h3>\n<p>اپنی فرد کا ID ریکارڈ سینٹر یا پرانی نقل سے معلوم کریں، پھر پولیس رپورٹ اور بیانِ حلفی جمع کروائیں۔ پرانی فرد منسوخ کر کے نئی جاری کر دی جائے گی۔</p>\n<h3>انگوٹھے کی تصدیق نہ ہو تو؟</h3>\n<p>پہلے NADRA سے اپنے فنگر پرنٹس اپ ڈیٹ کروائیں۔ اگر عمر زیادہ ہونے کی وجہ سے پھر بھی تصدیق نہ ہو تو شریک مالک یا گاؤں کے نمبردار کو ساتھ لائیں، تاکہ سروس سینٹر انچارج دستی تصدیق کا ٹوکن جاری کر سکے۔</p>\n<h3>ریکارڈ میں نام نہ ہو تو؟</h3>\n<p>اصل کاغذات کے ساتھ اراضی ریکارڈ سینٹر جا کر درستی کی درخواست دیں۔</p>\n<h2>کیا فرد کی کوئی میعاد ہوتی ہے؟</h2>\n<p>PLRA کے مطابق فرد کی کوئی مقررہ میعاد نہیں، لیکن زمین کی منتقلی یا انتقال سے معلومات بدل سکتی ہیں۔ اس لیے <strong>ہر سودے سے پہلے تازہ فرد ضرور لیں</strong>، چاہے بیچنے والا پرانی فرد دکھا رہا ہو۔</p>\n<h2>مزید مدد</h2>\n<p>تمام سرکاری پورٹلز کے لنکس ایک جگہ دیکھنے کے لیے ہماری <a href=\"https://www.assanzameen.com/tools/government-links?lang=ur\">سرکاری لنکس گائیڈ</a> کھولیں۔ PLRA سے شکایت یا رابطے کے لیے فون نمبر <strong>(042) 111-22-22-77</strong> ہے (پیر تا ہفتہ، صبح 8 سے شام 5 بجے تک)۔</p>\n<blockquote>یہ مضمون PLRA کی ویب سائٹ پر موجود معلومات کی بنیاد پر 1 نومبر 2026 کو لکھا گیا۔ آسان زمین سرکاری ادارہ نہیں ہے۔ فیس اور طریقہ کار بدل سکتے ہیں، اس لیے ادائیگی سے پہلے متعلقہ دفتر سے تصدیق کر لیں۔ یہ قانونی مشورہ نہیں ہے۔</blockquote>',
  'فرد,فرد ملکیت,PLRA,اراضی ریکارڈ سینٹر,online fard punjab,fard kaise hasil karein',
  '3',
  '0',
