-- 14. e-stamp-challan-32a-kaise-banayein-punjab-guide
INSERT INTO `posts` (`id`, `user_id`, `title`, `title_ur`, `slug`, `category`, `featured_image`, `summary`, `summary_ur`, `content`, `content_ur`, `tags`, `read_time`, `views_count`, `likes_count`, `is_featured`, `status`, `created_at`, `updated_at`) VALUES (
  NULL,
  COALESCE((SELECT u.`id` FROM `users` u WHERE u.`role` = 'admin' ORDER BY u.`id` LIMIT 1), (SELECT MIN(u2.`id`) FROM `users` u2)),
  'How to Get an e-Stamp in Punjab: Challan Form 32-A Step by Step',
  'ای-اسٹامپ کیسے بنوائیں؟ پنجاب میں چالان فارم 32-A بنانے اور جمع کروانے کا آسان طریقہ',
  'e-stamp-challan-32a-kaise-banayein-punjab-guide',
  'Taxes & Laws',
  NULL,
  'How to create Challan 32-A on the Punjab e-Stamp portal, pay it, verify an e-Stamp and pay a deficiency. A simple step by step guide.',
  'پنجاب میں ای-اسٹامپ کے لیے چالان 32-A بنانے، ادائیگی کرنے، اسٹامپ کی تصدیق اور کمی کی رقم جمع کروانے کا مرحلہ وار طریقہ۔',
  '<p>New property deals in Punjab now use <strong>e-Stamps</strong> instead of paper stamp papers. You do not need an account to create a challan, and the portal also works on a phone.</p>\n<h2>What is an e-Stamp?</h2>\n<p>It is the Government of Punjab\'s electronic system for generating and paying stamp duty online. There are two types: <strong>Judicial</strong> for court matters and <strong>Non-Judicial</strong> for property and business deeds.</p>\n<h2>How to create Challan 32-A</h2>\n<ol>\n<li>Open the <a href=\"https://es.punjab-zameen.gov.pk/eStampCitizenPortal/ChallanFormView/HomePage\" rel=\"noopener\" target=\"_blank\">e-Stamp portal</a> and click Generate Challan 32-A.</li>\n<li>Enter the district, tehsil, deed type, stamp paper type and purpose.</li>\n<li>Add the buyer and seller details. You can add more than one party.</li>\n<li>Enter the property address, land value and any construction value.</li>\n<li>Click Save. The system gives you a 16-digit challan ID, so keep it safe.</li>\n<li>Click Print Challan 32-A and print the PDF on plain paper.</li>\n</ol>\n<p>If a property dealer or lawyer is acting for you, enter their name, CNIC and contact details. For a power of attorney, tick the Power of Attorney box.</p>\n<h2>How is stamp duty calculated?</h2>\n<p>The system calculates it automatically. The rule is simple: <strong>duty is charged on your declared value or the DC valuation, whichever is higher.</strong> Declaring a lower price will not reduce the duty. See our <a href=\"https://www.assanzameen.com/blog/dc-valuation-kaise-check-karein-punjab\">DC valuation guide</a> to find the rate.</p>\n<h2>How to pay</h2>\n<p>Pay at any Bank of Punjab branch, or online through PSID and banking apps. Stamp duty, CVT and registration fee can be paid together on one challan.</p>\n<h2>Things to watch</h2>\n<ul>\n<li>You can edit a challan before payment, but not after.</li>\n<li>If the district or tehsil is wrong, create a new challan and do not use the old one.</li>\n<li>Each challan is valid for one transaction only.</li>\n<li>A challan is valid until the expiry shown on it, usually 90 days.</li>\n<li>An unpaid challan can be reprinted. A paid one cannot be reprinted from the portal.</li>\n</ul>\n<h2>How to verify an e-Stamp</h2>\n<p>Choose Verification through Web on the portal and enter the serial number, or scan the QR code. You will see the stamp status, amount, property and party details. This check is <strong>free</strong>, so do it before you accept any stamp in a deal.</p>\n<h2>If too little was paid</h2>\n<p>If less than the actual duty was paid, choose Pay Deficiency/Penalty on the home page and enter the stamp serial number. Deficiency is the unpaid balance, and penalty is an extra charge for late payment or an error. Each stamp needs its own challan.</p>\n<h2>Is old paper stamp still valid?</h2>\n<p>According to PLRA, only papers issued before e-Stamping began are valid. New transactions need an e-Stamp.</p>\n<h2>More help</h2>\n<p>Open our <a href=\"https://www.assanzameen.com/tools/government-links\">Government Links Guide</a> to see all the official portals in one place. To contact PLRA or make a complaint, call <strong>(042) 111-22-22-77</strong> (Monday to Saturday, 8:00 AM to 5:00 PM).</p>\n<blockquote>This article was written on 1 November 2026 from information on the PLRA website. Assan Zameen is not a government body. Fees and procedures can change, so confirm with the relevant office before paying. This is not legal advice.</blockquote>',
  '<p>پنجاب میں اب نئے سودوں کے لیے کاغذی اسٹامپ پیپر کی جگہ <strong>ای-اسٹامپ</strong> استعمال ہوتا ہے۔ اچھی بات یہ ہے کہ چالان بنانے کے لیے آپ کو کوئی اکاؤنٹ نہیں بنانا پڑتا اور یہ کام موبائل سے بھی ہو جاتا ہے۔</p>\n<h2>ای-اسٹامپ کیا ہے؟</h2>\n<p>یہ حکومتِ پنجاب کا الیکٹرانک نظام ہے جس سے اسٹامپ ڈیوٹی آن لائن بنائی اور ادا کی جاتی ہے۔ اسٹامپ پیپر کی دو قسمیں ہیں: <strong>جوڈیشل</strong> عدالتی معاملات کے لیے اور <strong>نان جوڈیشل</strong> جائیداد اور کاروباری دستاویزات کے لیے۔</p>\n<h2>چالان 32-A بنانے کا طریقہ</h2>\n<ol>\n<li><a href=\"https://es.punjab-zameen.gov.pk/eStampCitizenPortal/ChallanFormView/HomePage\" rel=\"noopener\" target=\"_blank\">ای-اسٹامپ پورٹل</a> کھولیں اور Generate Challan 32-A پر کلک کریں۔</li>\n<li>ضلع، تحصیل، دستاویز کی قسم، اسٹامپ پیپر کی قسم اور مقصد درج کریں۔</li>\n<li>خریدار اور فروخت کنندہ کی تفصیل بھریں۔ ایک سے زیادہ فریق بھی شامل کیے جا سکتے ہیں۔</li>\n<li>جائیداد کا پتہ، زمین کی مالیت اور تعمیر کی مالیت درج کریں۔</li>\n<li>Save کریں۔ سسٹم 16 ہندسوں کا چالان ID دے گا، اسے سنبھال کر رکھیں۔</li>\n<li>Print Challan 32-A پر کلک کریں اور PDF سادہ کاغذ پر پرنٹ کر لیں۔</li>\n</ol>\n<p>اگر کام پراپرٹی ڈیلر یا وکیل کے ذریعے ہو رہا ہے تو اس کا نام، شناختی کارڈ اور فون نمبر بھی دینا ہوگا۔ مختار نامے کی صورت میں Power of Attorney والا خانہ منتخب کریں۔</p>\n<h2>اسٹامپ ڈیوٹی کا حساب کیسے ہوتا ہے؟</h2>\n<p>سسٹم خود حساب لگاتا ہے۔ اس کا اصول سادہ ہے: <strong>آپ کی بتائی ہوئی قیمت اور DC ویلیوایشن میں سے جو زیادہ ہو، ڈیوٹی اسی پر بنتی ہے۔</strong> اس لیے کم قیمت لکھنے سے ڈیوٹی کم نہیں ہوگی۔ DC ریٹ جاننے کے لیے ہماری <a href=\"https://www.assanzameen.com/blog/dc-valuation-kaise-check-karein-punjab?lang=ur\">DC ویلیوایشن گائیڈ</a> پڑھیں۔</p>\n<h2>ادائیگی کیسے کریں؟</h2>\n<p>چالان کی رقم بینک آف پنجاب کی کسی بھی برانچ میں جمع کروائیں، یا PSID اور بینکنگ ایپس کے ذریعے آن لائن ادا کریں۔ اسٹامپ ڈیوٹی، CVT اور رجسٹریشن فیس ایک ہی چالان سے ادا ہو سکتی ہیں۔</p>\n<h2>چالان بناتے وقت ان باتوں کا خیال رکھیں</h2>\n<ul>\n<li>ادائیگی سے پہلے چالان میں تبدیلی ہو سکتی ہے، ادائیگی کے بعد نہیں۔</li>\n<li>ضلع یا تحصیل غلط ہو جائے تو نیا چالان بنائیں اور پرانا استعمال نہ کریں۔</li>\n<li>ایک چالان صرف ایک سودے کے لیے ہے، دوبارہ استعمال نہیں ہوتا۔</li>\n<li>چالان اپنی لکھی ہوئی مدت تک کارآمد رہتا ہے، جو عام طور پر 90 دن ہوتی ہے۔</li>\n<li>ادائیگی سے پہلے چالان دوبارہ پرنٹ ہو سکتا ہے، ادائیگی کے بعد پورٹل سے نہیں۔</li>\n</ul>\n<h2>ای-اسٹامپ اصلی ہے یا نہیں، کیسے چیک کریں؟</h2>\n<p>پورٹل پر Verification through Web منتخب کریں اور اسٹامپ کا سیریل نمبر لکھیں، یا QR کوڈ اسکین کریں۔ آپ کو اسٹامپ کی حیثیت، رقم، جائیداد اور فریقین کی تفصیل نظر آئے گی۔ یہ سہولت <strong>مفت</strong> ہے۔ کسی بھی سودے میں اسٹامپ قبول کرنے سے پہلے یہ جانچ ضرور کر لیں۔</p>\n<h2>اگر رقم کم جمع ہوئی ہو؟</h2>\n<p>اگر اصل ڈیوٹی سے کم رقم جمع ہوئی ہو تو ہوم پیج پر Pay Deficiency/Penalty منتخب کریں اور اسٹامپ کا سیریل نمبر لکھیں۔ کمی کا مطلب باقی ڈیوٹی ہے اور جرمانہ تاخیر یا غلطی پر اضافی رقم ہے۔ ہر اسٹامپ کے لیے الگ چالان بنتا ہے۔</p>\n<h2>کیا پرانا کاغذی اسٹامپ پیپر چلتا ہے؟</h2>\n<p>PLRA کے مطابق صرف ای-اسٹامپ نظام سے پہلے جاری ہونے والے پرانے پیپر کارآمد ہیں۔ نئے سودوں کے لیے ای-اسٹامپ ضروری ہے۔</p>\n<h2>مزید مدد</h2>\n<p>تمام سرکاری پورٹلز کے لنکس ایک جگہ دیکھنے کے لیے ہماری <a href=\"https://www.assanzameen.com/tools/government-links?lang=ur\">سرکاری لنکس گائیڈ</a> کھولیں۔ PLRA سے شکایت یا رابطے کے لیے فون نمبر <strong>(042) 111-22-22-77</strong> ہے (پیر تا ہفتہ، صبح 8 سے شام 5 بجے تک)۔</p>\n<blockquote>یہ مضمون PLRA کی ویب سائٹ پر موجود معلومات کی بنیاد پر 1 نومبر 2026 کو لکھا گیا۔ آسان زمین سرکاری ادارہ نہیں ہے۔ فیس اور طریقہ کار بدل سکتے ہیں، اس لیے ادائیگی سے پہلے متعلقہ دفتر سے تصدیق کر لیں۔ یہ قانونی مشورہ نہیں ہے۔</blockquote>',
