INSERT INTO `posts` (`id`, `user_id`, `title`, `title_ur`, `slug`, `category`, `featured_image`, `summary`, `summary_ur`, `content`, `content_ur`, `tags`, `read_time`, `views_count`, `likes_count`, `is_featured`, `status`, `created_at`, `updated_at`) VALUES (
  NULL,
  COALESCE((SELECT u.`id` FROM `users` u WHERE u.`role` = 'admin' ORDER BY u.`id` LIMIT 1), (SELECT MIN(u2.`id`) FROM `users` u2)),
  'What Is DC Valuation and How to Check the DC Rate Online in Punjab',
  'DC ویلیوایشن کیا ہے اور آن لائن کیسے چیک کریں؟ پنجاب میں زمین کا سرکاری ریٹ جاننے کا طریقہ',
  'dc-valuation-kaise-check-karein-punjab',
  'Taxes & Laws',
  NULL,
  'What DC valuation means, how it affects stamp duty, and how to check the official DC rate for your area online on the PLRA portal.',
  'DC ویلیوایشن کیا ہوتی ہے، اسٹامپ ڈیوٹی پر اس کا کیا اثر ہے، اور PLRA پورٹل سے گھر بیٹھے اپنے علاقے کا DC ریٹ کیسے معلوم کریں۔',
  '<p>In any plot deal you will hear the question \"what is the DC rate?\" That is because most official registry costs depend on it. You can now check it yourself online.</p>\n<h2>What is DC valuation?</h2>\n<p>It is the official property value notified by the District Collector (DC). Stamp duty, registration fees and other government charges are calculated from it.</p>\n<h2>Why it matters</h2>\n<p>The e-Stamp system charges duty on <strong>your declared value or the DC valuation, whichever is higher</strong>. So even if you write a lower price than the DC rate, duty is still charged on the DC rate. If too little duty was paid, the balance has to be paid on a separate challan.</p>\n<h2>How to check the DC rate online</h2>\n<ol>\n<li>Open the <a href=\"https://es.punjab-zameen.gov.pk/eStampCitizenPortal/ChallanFormView/RateOfChallanView?name=PropertyDCValuation\" rel=\"noopener\" target=\"_blank\">PLRA DC valuation portal</a>.</li>\n<li>Select the district, tehsil, revenue circle and area.</li>\n<li>Choose the land type: urban or rural, residential or commercial.</li>\n<li>Click Find Land Rate.</li>\n</ol>\n<p>You will see the DC rate per unit and the total value of the area you selected. <strong>Urban areas use marla and rural areas use acre.</strong> Click Reset to start again.</p>\n<h2>Do I need any documents?</h2>\n<p>No. Basic property details are enough, and the portal works on a phone.</p>\n<h2>Is the rate the same everywhere?</h2>\n<p>No. It changes with location, land type and property category, so do not assume a nearby area\'s rate applies to your plot.</p>\n<h2>If it says No Record Found</h2>\n<p>Check that the district, tehsil and revenue circle are correct. PLRA says some new areas may not be updated yet. In that case, ask your nearest Arazi Record Centre.</p>\n<h2>What to do next</h2>\n<ul>\n<li>Enter the rate in our <a href=\"https://www.assanzameen.com/tools/registry-tax-calculator\">Registry & Tax Calculator</a> to estimate the total cost.</li>\n<li>For the final amount, create an <a href=\"https://www.assanzameen.com/blog/e-stamp-challan-32a-kaise-banayein-punjab-guide\">e-Stamp challan</a>, because the system calculates it for you.</li>\n</ul>\n<h2>More help</h2>\n<p>Open our <a href=\"https://www.assanzameen.com/tools/government-links\">Government Links Guide</a> to see all the official portals in one place. To contact PLRA or make a complaint, call <strong>(042) 111-22-22-77</strong> (Monday to Saturday, 8:00 AM to 5:00 PM).</p>\n<blockquote>This article was written on 1 November 2026 from information on the PLRA website. Assan Zameen is not a government body. Fees and procedures can change, so confirm with the relevant office before paying. This is not legal advice.</blockquote>',
  '<p>پلاٹ کا سودا کرتے ہوئے اکثر سننے کو ملتا ہے کہ \"ڈی سی ریٹ کیا ہے؟\" اس کی وجہ یہ ہے کہ رجسٹری کا زیادہ تر سرکاری خرچ اسی ریٹ سے جڑا ہوتا ہے۔ اچھی خبر یہ ہے کہ اب یہ ریٹ جاننے کے لیے کسی کے پاس جانے کی ضرورت نہیں۔</p>\n<h2>DC ویلیوایشن کیا ہے؟</h2>\n<p>یہ جائیداد کی وہ سرکاری قیمت ہے جو ڈسٹرکٹ کلکٹر (DC) مقرر اور نوٹیفائی کرتا ہے۔ اسٹامپ ڈیوٹی، رجسٹریشن فیس اور دوسرے سرکاری چارجز کا حساب اسی بنیاد پر ہوتا ہے۔</p>\n<h2>یہ آپ کے لیے کیوں اہم ہے؟</h2>\n<p>ای-اسٹامپ سسٹم <strong>آپ کی بتائی ہوئی قیمت اور DC ویلیوایشن میں سے زیادہ والی رقم</strong> پر اسٹامپ ڈیوٹی لگاتا ہے۔ یعنی اگر آپ نے رجسٹری میں قیمت DC ریٹ سے کم لکھی، تب بھی ڈیوٹی DC ریٹ پر ہی بنے گی۔ اگر پہلے کم ڈیوٹی جمع ہوئی ہو تو باقی رقم الگ چالان سے جمع کروانی پڑتی ہے۔</p>\n<h2>آن لائن DC ریٹ چیک کرنے کا طریقہ</h2>\n<ol>\n<li><a href=\"https://es.punjab-zameen.gov.pk/eStampCitizenPortal/ChallanFormView/RateOfChallanView?name=PropertyDCValuation\" rel=\"noopener\" target=\"_blank\">PLRA کا DC ویلیوایشن پورٹل</a> کھولیں۔</li>\n<li>ضلع، تحصیل، ریونیو سرکل اور علاقہ منتخب کریں۔</li>\n<li>زمین کی قسم چنیں: شہری یا دیہی، رہائشی یا کمرشل۔</li>\n<li>Find Land Rate پر کلک کریں۔</li>\n</ol>\n<p>نتیجے میں فی یونٹ DC ریٹ اور منتخب رقبے کی کل مالیت نظر آئے گی۔ <strong>شہری علاقوں میں رقبہ مرلے میں اور دیہی علاقوں میں ایکڑ میں</strong> ہوتا ہے۔ دوبارہ شروع کرنے کے لیے Reset دبائیں۔</p>\n<h2>کیا اس کے لیے کاغذات چاہییں؟</h2>\n<p>نہیں۔ آن لائن DC ریٹ دیکھنے کے لیے کسی دستاویز کی ضرورت نہیں، بس جائیداد کی بنیادی تفصیل کافی ہے۔ پورٹل موبائل پر بھی چلتا ہے۔</p>\n<h2>کیا ہر جگہ ریٹ ایک جیسا ہوتا ہے؟</h2>\n<p>نہیں۔ ریٹ علاقے، زمین کی قسم اور جائیداد کی کیٹیگری کے ساتھ بدلتا ہے۔ اس لیے ساتھ والی آبادی کا ریٹ اپنے پلاٹ پر لاگو نہ سمجھیں۔</p>\n<h2>اگر No Record Found لکھا آئے؟</h2>\n<p>پہلے چیک کریں کہ ضلع، تحصیل اور ریونیو سرکل درست منتخب ہیں۔ PLRA کے مطابق کچھ نئے علاقے ابھی اپ ڈیٹ نہیں ہوئے ہوتے۔ ایسی صورت میں اپنے قریبی اراضی ریکارڈ سینٹر سے پوچھ لیں۔</p>\n<h2>DC ریٹ معلوم ہونے کے بعد کیا کریں؟</h2>\n<ul>\n<li>یہ ریٹ ہمارے <a href=\"https://www.assanzameen.com/tools/registry-tax-calculator?lang=ur\">رجسٹری اور ٹیکس کیلکولیٹر</a> میں ڈال کر کل خرچ کا اندازہ لگائیں۔</li>\n<li>حتمی رقم کے لیے <a href=\"https://www.assanzameen.com/blog/e-stamp-challan-32a-kaise-banayein-punjab-guide?lang=ur\">ای-اسٹامپ کا چالان</a> بنائیں، کیونکہ سسٹم خود درست حساب لگاتا ہے۔</li>\n</ul>\n<h2>مزید مدد</h2>\n<p>تمام سرکاری پورٹلز کے لنکس ایک جگہ دیکھنے کے لیے ہماری <a href=\"https://www.assanzameen.com/tools/government-links?lang=ur\">سرکاری لنکس گائیڈ</a> کھولیں۔ PLRA سے شکایت یا رابطے کے لیے فون نمبر <strong>(042) 111-22-22-77</strong> ہے (پیر تا ہفتہ، صبح 8 سے شام 5 بجے تک)۔</p>\n<blockquote>یہ مضمون PLRA کی ویب سائٹ پر موجود معلومات کی بنیاد پر 1 نومبر 2026 کو لکھا گیا۔ آسان زمین سرکاری ادارہ نہیں ہے۔ فیس اور طریقہ کار بدل سکتے ہیں، اس لیے ادائیگی سے پہلے متعلقہ دفتر سے تصدیق کر لیں۔ یہ قانونی مشورہ نہیں ہے۔</blockquote>',
