-- 16. nayi-registry-ka-tareeqa-e-registration-punjab-steps
INSERT INTO `posts` (`id`, `user_id`, `title`, `title_ur`, `slug`, `category`, `featured_image`, `summary`, `summary_ur`, `content`, `content_ur`, `tags`, `read_time`, `views_count`, `likes_count`, `is_featured`, `status`, `created_at`, `updated_at`) VALUES (
  NULL,
  COALESCE((SELECT u.`id` FROM `users` u WHERE u.`role` = 'admin' ORDER BY u.`id` LIMIT 1), (SELECT MIN(u2.`id`) FROM `users` u2)),
  'How to Register Property in Punjab: e-Registration Steps Explained',
  'نئی رجسٹری کیسے کروائیں؟ پنجاب کے ای-رجسٹریشن پورٹل کے مراحل آسان الفاظ میں',
  'nayi-registry-ka-tareeqa-e-registration-punjab-steps',
  'Property Guides',
  NULL,
  'The steps of a property registry in Punjab: challan, portal login, party details, statements before the Sub-Registrar and issue of the deed.',
  'پنجاب میں جائیداد کی رجسٹری کے مراحل: چالان، پورٹل پر لاگ اِن، فریقین کی تفصیل، سب رجسٹرار کے سامنے بیان اور دستاویز کا اجرا۔',
  '<p>A registry is the legal document that records the transfer of property from one party to another. In Punjab this is done digitally, under the supervision of PLRA and the Board of Revenue.</p>\n<h2>Prepare first</h2>\n<ul>\n<li>A <a href=\"https://www.assanzameen.com/blog/fard-kaise-hasil-karein-punjab-online-arc-guide\">fresh sale fard</a> in the seller\'s name</li>\n<li>CNIC details of the buyer, seller and witnesses</li>\n<li>The <a href=\"https://www.assanzameen.com/blog/dc-valuation-kaise-check-karein-punjab\">DC rate</a> of the area</li>\n</ul>\n<h2>e-Registration steps</h2>\n<h3>1. Create the challan and pay the fees</h3>\n<p>Create an e-Stamp challan and pay stamp duty, FBR taxes, registration fee, mutation fee and related charges. <a href=\"https://www.assanzameen.com/blog/e-stamp-challan-32a-kaise-banayein-punjab-guide\">See how to create a challan</a>.</p>\n<h3>2. Create a portal login</h3>\n<p>Open the <a href=\"https://eregistration.punjab-zameen.gov.pk/\" rel=\"noopener\" target=\"_blank\">e-Registration portal</a> and create the required user login.</p>\n<h3>3. Start the request</h3>\n<p>Start a new deed registration in the system.</p>\n<h3>4. Verify the challan and enter the parties</h3>\n<p>Verify the paid challans and carefully enter the buyer, seller and witness details. A mistake in a name or CNIC can cause problems later.</p>\n<h3>5. Sub-Registrar process</h3>\n<p>The request goes to the Sub-Registrar, where statements of the parties and witnesses are recorded.</p>\n<h3>6. Issue of the document</h3>\n<p>The registered document is issued, with the Bahi number and document number assigned automatically.</p>\n<h2>What about the mutation?</h2>\n<p>According to PLRA, <strong>in online mouzas the mutation of an e-Registry is processed automatically</strong>, so the registry and mutation are approved together. If you have an old registry with a pending mutation, apply to the District Collector. After verification and permission, you can complete the mutation at an Arazi Record Centre.</p>\n<h2>If a name is wrong in the registry</h2>\n<p>First get the registry corrected at the Sub-Registrar office. It can then be updated in the land record at an Arazi Record Centre.</p>\n<h2>Need a copy of an old registry?</h2>\n<p>You can find a deed registered earlier on the <a href=\"https://rod.pulse.gop.pk/\" rel=\"noopener\" target=\"_blank\">PLRA registered deeds portal</a>.</p>\n<h2>If a party is overseas</h2>\n<p>The Sub-Registrar appoints an official at the Pakistan mission abroad as commission to record the statement, with thumb impression, photo and video. The other parties give their statements in person in Punjab.</p>\n<h2>More help</h2>\n<p>Open our <a href=\"https://www.assanzameen.com/tools/government-links\">Government Links Guide</a> to see all the official portals in one place. To contact PLRA or make a complaint, call <strong>(042) 111-22-22-77</strong> (Monday to Saturday, 8:00 AM to 5:00 PM).</p>\n<blockquote>This article was written on 1 November 2026 from information on the PLRA website. Assan Zameen is not a government body. Fees and procedures can change, so confirm with the relevant office before paying. This is not legal advice.</blockquote>',
  '<p>رجسٹری وہ قانونی دستاویز ہے جو جائیداد کی ملکیت ایک فریق سے دوسرے کو منتقل ہونے کا ریکارڈ رکھتی ہے۔ پنجاب میں یہ کام PLRA اور بورڈ آف ریونیو کی نگرانی میں ڈیجیٹل طریقے سے ہوتا ہے۔</p>\n<h2>رجسٹری سے پہلے یہ تیاری کر لیں</h2>\n<ul>\n<li>بیچنے والے کے نام کی <a href=\"https://www.assanzameen.com/blog/fard-kaise-hasil-karein-punjab-online-arc-guide?lang=ur\">تازہ فرد برائے بیع</a></li>\n<li>خریدار، فروخت کنندہ اور گواہوں کے شناختی کارڈ کی تفصیل</li>\n<li>علاقے کا <a href=\"https://www.assanzameen.com/blog/dc-valuation-kaise-check-karein-punjab?lang=ur\">DC ریٹ</a></li>\n</ul>\n<h2>ای-رجسٹریشن کے مراحل</h2>\n<h3>1. چالان بنائیں اور فیس جمع کروائیں</h3>\n<p>ای-اسٹامپ چالان بنا کر اسٹامپ ڈیوٹی، FBR ٹیکس، رجسٹریشن فیس اور انتقال فیس وغیرہ ادا کریں۔ <a href=\"https://www.assanzameen.com/blog/e-stamp-challan-32a-kaise-banayein-punjab-guide?lang=ur\">چالان بنانے کا طریقہ یہاں پڑھیں</a>۔</p>\n<h3>2. پورٹل پر یوزر بنائیں</h3>\n<p><a href=\"https://eregistration.punjab-zameen.gov.pk/\" rel=\"noopener\" target=\"_blank\">ای-رجسٹریشن پورٹل</a> کھول کر مطلوبہ یوزر لاگ اِن بنائیں۔</p>\n<h3>3. درخواست شروع کریں</h3>\n<p>سسٹم میں رجسٹری کی نئی کارروائی شروع کریں۔</p>\n<h3>4. چالان کی تصدیق اور فریقین کی تفصیل</h3>\n<p>ادا شدہ چالان کی تصدیق کریں اور خریدار، فروخت کنندہ اور گواہوں کی تفصیل احتیاط سے درج کریں۔ نام اور شناختی کارڈ نمبر میں غلطی بعد میں مسئلہ بن سکتی ہے۔</p>\n<h3>5. سب رجسٹرار کے پاس کارروائی</h3>\n<p>درخواست سب رجسٹرار کو جاتی ہے، جہاں فریقین اور گواہوں کے بیانات ریکارڈ ہوتے ہیں۔</p>\n<h3>6. دستاویز کا اجرا</h3>\n<p>آخر میں رجسٹرڈ دستاویز جاری ہوتی ہے، جس پر بہی نمبر اور دستاویز نمبر خود بخود لگ جاتے ہیں۔</p>\n<h2>رجسٹری کے بعد انتقال کا کیا ہوگا؟</h2>\n<p>PLRA کے مطابق <strong>آن لائن موضع جات میں ای-رجسٹری کا انتقال خود بخود ہو جاتا ہے</strong>، یعنی رجسٹری اور انتقال ایک ساتھ منظور ہوتے ہیں۔ اگر آپ کے پاس پرانی رجسٹری ہے جس کا انتقال باقی ہے تو ڈسٹرکٹ کلکٹر کو درخواست دیں۔ وہ تصدیق کے بعد اجازت دے گا، پھر اراضی ریکارڈ سینٹر سے انتقال کروایا جا سکتا ہے۔</p>\n<h2>اگر رجسٹری میں نام غلط لکھا جائے؟</h2>\n<p>پہلے سب رجسٹرار آفس سے رجسٹری درست کروائیں، اس کے بعد اراضی ریکارڈ سینٹر سے زمین کے ریکارڈ میں تبدیلی کروائی جا سکتی ہے۔</p>\n<h2>پرانی رجسٹری کی نقل چاہیے؟</h2>\n<p>پہلے سے ہوئی ای-رجسٹری کی نقل <a href=\"https://rod.pulse.gop.pk/\" rel=\"noopener\" target=\"_blank\">PLRA کے رجسٹرڈ دستاویزات کے پورٹل</a> سے تلاش کی جا سکتی ہے۔</p>\n<h2>بیرون ملک فریق ہو تو؟</h2>\n<p>سب رجسٹرار بیرون ملک پاکستانی مشن کے افسر کو کمیشن مقرر کرتا ہے، جو انگوٹھے کے نشان، تصویر اور ویڈیو کے ساتھ بیان ریکارڈ کرتا ہے۔ باقی فریق پنجاب میں خود بیان دیتے ہیں۔</p>\n<h2>مزید مدد</h2>\n<p>تمام سرکاری پورٹلز کے لنکس ایک جگہ دیکھنے کے لیے ہماری <a href=\"https://www.assanzameen.com/tools/government-links?lang=ur\">سرکاری لنکس گائیڈ</a> کھولیں۔ PLRA سے شکایت یا رابطے کے لیے فون نمبر <strong>(042) 111-22-22-77</strong> ہے (پیر تا ہفتہ، صبح 8 سے شام 5 بجے تک)۔</p>\n<blockquote>یہ مضمون PLRA کی ویب سائٹ پر موجود معلومات کی بنیاد پر 1 نومبر 2026 کو لکھا گیا۔ آسان زمین سرکاری ادارہ نہیں ہے۔ فیس اور طریقہ کار بدل سکتے ہیں، اس لیے ادائیگی سے پہلے متعلقہ دفتر سے تصدیق کر لیں۔ یہ قانونی مشورہ نہیں ہے۔</blockquote>',
  'رجسٹری,e-registration punjab,ای رجسٹریشن,سب رجسٹرار,PLRA,registry kaise karein',
  '2',
  '0',
  '0',
