-- 17. bai-zubani-intiqal-ka-tareeqa-fee-punjab
INSERT INTO `posts` (`id`, `user_id`, `title`, `title_ur`, `slug`, `category`, `featured_image`, `summary`, `summary_ur`, `content`, `content_ur`, `tags`, `read_time`, `views_count`, `likes_count`, `is_featured`, `status`, `created_at`, `updated_at`) VALUES (
  NULL,
  COALESCE((SELECT u.`id` FROM `users` u WHERE u.`role` = 'admin' ORDER BY u.`id` LIMIT 1), (SELECT MIN(u2.`id`) FROM `users` u2)),
  'Oral Mutation (Bai Zubani) in Punjab: Procedure, Documents and Fees',
  'زبانی انتقال (بیع زبانی) کا طریقہ: اراضی ریکارڈ سینٹر میں زمین کی منتقلی مرحلہ وار',
  'bai-zubani-intiqal-ka-tareeqa-fee-punjab',
  'Property Guides',
  NULL,
  'What a bai zubani mutation is, the documents you need, where to pay the fees, and where to appeal if a mutation is wrong. Based on PLRA information.',
  'بیع زبانی انتقال کیا ہے، کون سے کاغذات چاہییں، فیس کہاں جمع ہوتی ہے، اور غلط انتقال ہونے پر اپیل کہاں کریں۔ PLRA کی معلومات پر مبنی گائیڈ۔',
  '<p>After a land deal, the job is not finished until the new owner\'s name is in the official record. This step is called a <strong>mutation (intiqal)</strong>. This guide explains the oral sale mutation.</p>\n<h2>What do these terms mean?</h2>\n<p>A mutation transfers ownership rights in land and updates the official record. In a <strong>bai zubani</strong> mutation, the buyer, seller and witnesses give oral statements before the Revenue Officer at an Arazi Record Centre.</p>\n<h2>Documents needed</h2>\n<ul>\n<li>A valid CNIC</li>\n<li>Ownership documents, such as a registry, fard or mutation number</li>\n</ul>\n<h2>The procedure</h2>\n<ol>\n<li>Go to the relevant Arazi Record Centre with your CNIC and property details.</li>\n<li>Get a token after NADRA biometric verification.</li>\n<li>Give the property details for the mutation entry.</li>\n<li>Pay the required fees at the bank or online.</li>\n<li>Appear before the ADLR (Revenue Officer) with the buyer and witnesses.</li>\n<li>The officer records the statements and approves the mutation.</li>\n</ol>\n<p>If you bring the buyer and witnesses with you, PLRA says this can be done <strong>in one visit</strong>. Once approved, the new owner\'s name appears in the jamabandi straight away.</p>\n<h2>Fees and where to pay</h2>\n<p>The PLRA website lists four types of fees on an oral sale mutation:</p>\n<ul>\n<li>Mutation fee: 3%</li>\n<li>District Council fee: 1%</li>\n<li>FBR advance tax on the buyer (section 236-K)</li>\n<li>FBR gain tax on the seller (section 236-C)</li>\n</ul>\n<p>FBR tax differs for filers and non-filers and changes with the budget. Before making a challan, <a href=\"https://e.fbr.gov.pk/atl/\" rel=\"noopener\" target=\"_blank\">check your filer status</a> and confirm the current rate with the centre or FBR.</p>\n<p>Mutation and local government fees are paid at the Bank of Punjab counter at the centre or online through PSID. The FBR challan is generated on the FBR website.</p>\n<h2>Can I use any centre?</h2>\n<p>The entry can be made at any Arazi Record Centre in Punjab, but the statement is recorded before the Revenue Officer of the area where the land is. A mutation done by the patwari at a Dahi Markaz Mall is just as legally valid.</p>\n<h2>How to verify a mutation</h2>\n<p>Scan the QR code on the mutation copy. You can also get an attested copy of an approved mutation by paying the required fee.</p>\n<h2>If something goes wrong</h2>\n<ul>\n<li><strong>A mutation was wrongly approved:</strong> appeal to the Assistant Commissioner for inheritance mutations and to the District Collector in other cases. You can also go to the civil court.</li>\n<li><strong>Nobody is attesting your mutation:</strong> apply to the Assistant Commissioner, Deputy Commissioner or PLRA.</li>\n<li><strong>You paid the fee but the deal was cancelled:</strong> record a cancellation statement before the ADLR, then apply to the Assistant Commissioner for a refund.</li>\n</ul>\n<h2>More help</h2>\n<p>Open our <a href=\"https://www.assanzameen.com/tools/government-links\">Government Links Guide</a> to see all the official portals in one place. To contact PLRA or make a complaint, call <strong>(042) 111-22-22-77</strong> (Monday to Saturday, 8:00 AM to 5:00 PM).</p>\n<blockquote>This article was written on 1 November 2026 from information on the PLRA website. Assan Zameen is not a government body. Fees and procedures can change, so confirm with the relevant office before paying. This is not legal advice.</blockquote>',
  '<p>زمین کا سودا ہو جانے کے بعد جب تک سرکاری ریکارڈ میں نئے مالک کا نام نہ آئے، کام پورا نہیں ہوتا۔ اس کام کو <strong>انتقال</strong> کہتے ہیں۔ اس مضمون میں ہم بیع زبانی انتقال کا طریقہ سمجھائیں گے۔</p>\n<h2>انتقال اور بیع زبانی کا مطلب</h2>\n<p>انتقال زمین کے مالکانہ حقوق کی منتقلی ہے، جس سے سرکاری ریکارڈ میں نئے مالک کا نام آ جاتا ہے۔ <strong>بیع زبانی</strong> میں خریدار، فروخت کنندہ اور گواہ اراضی ریکارڈ سینٹر میں ریونیو افسر کے سامنے زبانی بیان دیتے ہیں۔</p>\n<h2>کون سے کاغذات چاہییں؟</h2>\n<ul>\n<li>کارآمد شناختی کارڈ</li>\n<li>ملکیت کے کاغذات، جیسے رجسٹری، فرد یا انتقال نمبر</li>\n</ul>\n<h2>انتقال کا طریقہ</h2>\n<ol>\n<li>شناختی کارڈ اور جائیداد کی تفصیل لے کر متعلقہ اراضی ریکارڈ سینٹر جائیں۔</li>\n<li>NADRA بائیو میٹرک تصدیق کے بعد ٹوکن لیں۔</li>\n<li>انتقال کے اندراج کے لیے جائیداد کی تفصیل دیں۔</li>\n<li>مطلوبہ فیس بینک میں یا آن لائن جمع کروائیں۔</li>\n<li>خریدار اور گواہوں کے ساتھ ADLR (ریونیو افسر) کے سامنے پیش ہوں۔</li>\n<li>افسر بیان ریکارڈ کر کے انتقال منظور کرتا ہے۔</li>\n</ol>\n<p>اگر آپ خریدار اور گواہوں کو ساتھ لے کر جائیں تو PLRA کے مطابق یہ کام <strong>ایک ہی چکر میں</strong> ہو سکتا ہے۔ منظوری کے فوراً بعد جمع بندی میں نئے مالک کا نام آ جاتا ہے۔</p>\n<h2>فیس کتنی ہے اور کہاں جمع ہوگی؟</h2>\n<p>PLRA کی ویب سائٹ کے مطابق زبانی انتقال پر چار طرح کی فیس لگتی ہے:</p>\n<ul>\n<li>انتقال فیس: 3%</li>\n<li>ڈسٹرکٹ کونسل فیس: 1%</li>\n<li>خریدار کے لیے FBR ایڈوانس ٹیکس (سیکشن 236-K)</li>\n<li>فروخت کنندہ کے لیے FBR گین ٹیکس (سیکشن 236-C)</li>\n</ul>\n<p>FBR ٹیکس فائلر اور نان فائلر کے لیے مختلف ہوتا ہے اور اس کے ریٹ بجٹ کے ساتھ بدلتے رہتے ہیں، اس لیے چالان بنانے سے پہلے <a href=\"https://e.fbr.gov.pk/atl/\" rel=\"noopener\" target=\"_blank\">اپنا فائلر اسٹیٹس</a> چیک کریں اور موجودہ ریٹ سینٹر یا FBR سے کنفرم کریں۔</p>\n<p>انتقال اور لوکل گورنمنٹ کی فیس سینٹر پر بینک آف پنجاب کے کاؤنٹر یا PSID کے ذریعے آن لائن جمع ہوتی ہے۔ FBR ٹیکس کا چالان FBR کی ویب سائٹ سے بنایا جاتا ہے۔</p>\n<h2>کیا کسی بھی سینٹر سے انتقال ہو سکتا ہے؟</h2>\n<p>اندراج پنجاب کے کسی بھی اراضی ریکارڈ سینٹر سے ہو سکتا ہے، لیکن بیان اسی ریونیو افسر کے سامنے ہوگا جس کے علاقے میں زمین ہے۔ دیہی مرکز مال میں پٹواری کا کیا ہوا انتقال بھی قانونی طور پر اتنا ہی درست ہے۔</p>\n<h2>انتقال کی تصدیق کیسے کریں؟</h2>\n<p>انتقال کی نقل پر چھپا QR کوڈ اسکین کریں۔ مقررہ فیس جمع کروا کر منظور شدہ انتقال کی تصدیق شدہ نقل بھی لی جا سکتی ہے۔</p>\n<h2>اگر کوئی مسئلہ ہو جائے؟</h2>\n<ul>\n<li><strong>غلط انتقال منظور ہو گیا:</strong> وراثتی انتقال میں اسسٹنٹ کمشنر کے پاس اور باقی معاملات میں ڈسٹرکٹ کلکٹر کے پاس اپیل کریں۔ سول عدالت سے بھی رجوع کیا جا سکتا ہے۔</li>\n<li><strong>انتقال تصدیق نہیں ہو رہا:</strong> اسسٹنٹ کمشنر، ڈپٹی کمشنر یا PLRA کو درخواست دیں۔</li>\n<li><strong>فیس جمع کروا کر سودا منسوخ ہو گیا:</strong> ADLR کے سامنے منسوخی کا بیان دیں، پھر فیس کی واپسی کے لیے اسسٹنٹ کمشنر کو درخواست دیں۔</li>\n</ul>\n<h2>مزید مدد</h2>\n<p>تمام سرکاری پورٹلز کے لنکس ایک جگہ دیکھنے کے لیے ہماری <a href=\"https://www.assanzameen.com/tools/government-links?lang=ur\">سرکاری لنکس گائیڈ</a> کھولیں۔ PLRA سے شکایت یا رابطے کے لیے فون نمبر <strong>(042) 111-22-22-77</strong> ہے (پیر تا ہفتہ، صبح 8 سے شام 5 بجے تک)۔</p>\n<blockquote>یہ مضمون PLRA کی ویب سائٹ پر موجود معلومات کی بنیاد پر 1 نومبر 2026 کو لکھا گیا۔ آسان زمین سرکاری ادارہ نہیں ہے۔ فیس اور طریقہ کار بدل سکتے ہیں، اس لیے ادائیگی سے پہلے متعلقہ دفتر سے تصدیق کر لیں۔ یہ قانونی مشورہ نہیں ہے۔</blockquote>',
  'انتقال,بیع زبانی,mutation punjab,intiqal,اراضی ریکارڈ سینٹر,ADLR',
  '3',
  '0',
  '0',
