-- 18. wirasati-intiqal-ka-tareeqa-punjab-kaghzat
INSERT INTO `posts` (`id`, `user_id`, `title`, `title_ur`, `slug`, `category`, `featured_image`, `summary`, `summary_ur`, `content`, `content_ur`, `tags`, `read_time`, `views_count`, `likes_count`, `is_featured`, `status`, `created_at`, `updated_at`) VALUES (
  NULL,
  COALESCE((SELECT u.`id` FROM `users` u WHERE u.`role` = 'admin' ORDER BY u.`id` LIMIT 1), (SELECT MIN(u2.`id`) FROM `users` u2)),
  'Inheritance Mutation in Punjab: How to Transfer Land to the Legal Heirs',
  'وراثتی انتقال کیسے کروائیں؟ پنجاب میں والد یا والدہ کی زمین ورثاء کے نام کرنے کا طریقہ',
  'wirasati-intiqal-ka-tareeqa-punjab-kaghzat',
  'Property Guides',
  NULL,
  'How to transfer land to heirs after a death in Punjab: documents needed, family tree verification, the Arazi Record Centre process and the right to appeal.',
  'وفات کے بعد زمین ورثاء کے نام کروانے کا طریقہ: درکار کاغذات، شجرہ نسب کی تصدیق، اراضی ریکارڈ سینٹر کی کارروائی اور اپیل کا حق۔',
  '<p>After a family member dies, land matters often stay pending for years. Until the inheritance mutation is done, the land remains in the deceased\'s name, which makes it hard for the heirs to sell or divide it. The process itself is fairly simple.</p>\n<h2>Who can apply?</h2>\n<p>According to PLRA, <strong>any legal heir</strong> can start the process at an Arazi Record Centre.</p>\n<h2>Documents needed</h2>\n<ul>\n<li>Death certificate</li>\n<li>FRC form (Family Registration Certificate)</li>\n<li>Affidavit</li>\n<li>Property details</li>\n<li>CNIC copies of all legal heirs</li>\n</ul>\n<h2>The procedure</h2>\n<ol>\n<li>Take all the documents to an Arazi Record Centre.</li>\n<li>The file goes to the field staff, who verify the <strong>shajra nasab</strong> (family tree).</li>\n<li>After the report, the inheritance mutation is attested at the centre.</li>\n</ol>\n<h2>Understand the shares first</h2>\n<p>Everyone in the family should know their share before the process starts, as this reduces later disputes. Our free <a href=\"https://www.assanzameen.com/tools/inheritance-calculator\">Inheritance Calculator</a> estimates the shares of a spouse, parents, children and full siblings. If grandchildren or other relatives are involved, please ask a scholar or lawyer.</p>\n<h2>Can the mutation be verified?</h2>\n<p>Yes. An approved mutation copy has a QR code you can scan. After approval the jamabandi changes straight away, and each heir can get a <a href=\"https://www.assanzameen.com/blog/fard-kaise-hasil-karein-punjab-online-arc-guide\">fard</a> showing their share.</p>\n<h2>If an heir is left out or a share is wrong</h2>\n<p>If an inheritance mutation is wrongly approved, you can <strong>appeal to the Assistant Commissioner</strong> or go to the civil court. Act early, because correction takes longer once a mutation is part of the jamabandi.</p>\n<h2>How is the land divided afterwards?</h2>\n<p>After an inheritance mutation, land usually stays in a joint holding. If each heir wants a separate piece, you need to apply for <a href=\"https://www.assanzameen.com/blog/zameen-ki-taqseem-online-darkhwast-punjab\">land partition</a>.</p>\n<h2>More help</h2>\n<p>Open our <a href=\"https://www.assanzameen.com/tools/government-links\">Government Links Guide</a> to see all the official portals in one place. To contact PLRA or make a complaint, call <strong>(042) 111-22-22-77</strong> (Monday to Saturday, 8:00 AM to 5:00 PM).</p>\n<blockquote>This article was written on 1 November 2026 from information on the PLRA website. Assan Zameen is not a government body. Fees and procedures can change, so confirm with the relevant office before paying. This is not legal advice.</blockquote>',
  '<p>کسی پیارے کی وفات کے بعد زمین کا معاملہ اکثر سالوں تک لٹکا رہتا ہے۔ جب تک وراثتی انتقال نہ ہو، زمین ریکارڈ میں مرحوم ہی کے نام رہتی ہے اور ورثاء کو بیچنے یا تقسیم کرنے میں مشکل پیش آتی ہے۔ یہ عمل اصل میں کافی سیدھا ہے۔</p>\n<h2>درخواست کون دے سکتا ہے؟</h2>\n<p>PLRA کے مطابق <strong>کوئی بھی قانونی وارث</strong> اراضی ریکارڈ سینٹر جا کر یہ کارروائی شروع کر سکتا ہے۔ تمام ورثاء کا اکٹھے جانا اس مرحلے پر شرط کے طور پر نہیں بتایا گیا۔</p>\n<h2>کون سے کاغذات چاہییں؟</h2>\n<ul>\n<li>وفات کا سرٹیفکیٹ</li>\n<li>FRC فارم (فیملی رجسٹریشن سرٹیفکیٹ)</li>\n<li>بیانِ حلفی</li>\n<li>جائیداد کی تفصیل</li>\n<li>تمام قانونی ورثاء کے شناختی کارڈ کی نقول</li>\n</ul>\n<h2>وراثتی انتقال کا طریقہ</h2>\n<ol>\n<li>تمام کاغذات لے کر اراضی ریکارڈ سینٹر جائیں۔</li>\n<li>فائل فیلڈ اسٹاف کو بھیجی جاتی ہے، جو <strong>شجرہ نسب</strong> کی تصدیق کرتا ہے۔</li>\n<li>رپورٹ آنے کے بعد سینٹر پر وراثتی انتقال تصدیق کر دیا جاتا ہے۔</li>\n</ol>\n<h2>حصوں کا حساب پہلے خود سمجھ لیں</h2>\n<p>کارروائی شروع کرنے سے پہلے خاندان میں سب کو معلوم ہونا چاہیے کہ کس کا کتنا حصہ بنتا ہے۔ اس سے بعد کے جھگڑے کم ہوتے ہیں۔ ہمارا مفت <a href=\"https://www.assanzameen.com/tools/inheritance-calculator?lang=ur\">وراثت کیلکولیٹر</a> بیوی، شوہر، والدین، اولاد اور حقیقی بہن بھائیوں کے حصوں کا اندازہ بتاتا ہے۔ پوتے پوتیوں یا دوسرے رشتہ داروں کا معاملہ ہو تو عالم یا وکیل سے ضرور پوچھیں۔</p>\n<h2>کیا اس انتقال کی تصدیق ہو سکتی ہے؟</h2>\n<p>جی ہاں۔ منظور شدہ انتقال کی نقل پر QR کوڈ ہوتا ہے، جسے اسکین کر کے تفصیل دیکھی جا سکتی ہے۔ منظوری کے بعد جمع بندی میں نام فوراً تبدیل ہو جاتا ہے۔ اس کے بعد ہر وارث اپنی <a href=\"https://www.assanzameen.com/blog/fard-kaise-hasil-karein-punjab-online-arc-guide?lang=ur\">فرد</a> نکلوا کر اپنا حصہ دیکھ سکتا ہے۔</p>\n<h2>اگر کسی وارث کا نام رہ جائے یا حصہ غلط لگ جائے؟</h2>\n<p>وراثتی انتقال غلط منظور ہونے کی صورت میں <strong>اسسٹنٹ کمشنر کے پاس اپیل</strong> کی جا سکتی ہے۔ سول عدالت سے بھی رجوع کیا جا سکتا ہے۔ جتنی جلد قدم اٹھائیں اتنا بہتر ہے، کیونکہ انتقال کے جمع بندی میں شامل ہونے کے بعد درستی کا راستہ لمبا ہو جاتا ہے۔</p>\n<h2>وراثت کے بعد زمین الگ کیسے ہوگی؟</h2>\n<p>وراثتی انتقال کے بعد بھی زمین عموماً مشترکہ کھاتے میں رہتی ہے۔ ہر وارث کو الگ ٹکڑا چاہیے تو <a href=\"https://www.assanzameen.com/blog/zameen-ki-taqseem-online-darkhwast-punjab?lang=ur\">زمین کی تقسیم کی درخواست</a> دینا ہوگی۔</p>\n<h2>مزید مدد</h2>\n<p>تمام سرکاری پورٹلز کے لنکس ایک جگہ دیکھنے کے لیے ہماری <a href=\"https://www.assanzameen.com/tools/government-links?lang=ur\">سرکاری لنکس گائیڈ</a> کھولیں۔ PLRA سے شکایت یا رابطے کے لیے فون نمبر <strong>(042) 111-22-22-77</strong> ہے (پیر تا ہفتہ، صبح 8 سے شام 5 بجے تک)۔</p>\n<blockquote>یہ مضمون PLRA کی ویب سائٹ پر موجود معلومات کی بنیاد پر 1 نومبر 2026 کو لکھا گیا۔ آسان زمین سرکاری ادارہ نہیں ہے۔ فیس اور طریقہ کار بدل سکتے ہیں، اس لیے ادائیگی سے پہلے متعلقہ دفتر سے تصدیق کر لیں۔ یہ قانونی مشورہ نہیں ہے۔</blockquote>',
  'وراثتی انتقال,inheritance mutation punjab,وراثت,شجرہ نسب,FRC,اراضی ریکارڈ سینٹر',
  '2',
  '0',
