-- 19. land-record-durusti-fard-badar-naam-theek-punjab
INSERT INTO `posts` (`id`, `user_id`, `title`, `title_ur`, `slug`, `category`, `featured_image`, `summary`, `summary_ur`, `content`, `content_ur`, `tags`, `read_time`, `views_count`, `likes_count`, `is_featured`, `status`, `created_at`, `updated_at`) VALUES (
  NULL,
  COALESCE((SELECT u.`id` FROM `users` u WHERE u.`role` = 'admin' ORDER BY u.`id` LIMIT 1), (SELECT MIN(u2.`id`) FROM `users` u2)),
  'How to Correct a Land Record in Punjab: Fard Badar and Name Correction',
  'زمین کے ریکارڈ میں غلطی کیسے ٹھیک کروائیں؟ فرد بدر اور نام کی درستی کا طریقہ',
  'land-record-durusti-fard-badar-naam-theek-punjab',
  'Property Guides',
  NULL,
  'Wrong name or area on your fard? The four types of land record correction, documents needed, who approves them and when a court order is required.',
  'فرد میں نام، رقبہ یا اندراج غلط ہے؟ ریکارڈ کی درستی کی چار اقسام، ضروری کاغذات، کون منظور کرتا ہے اور عدالتی حکم کب ضروری ہوتا ہے۔',
  '<p>Sometimes a fard shows a misspelled name or a different area. There is no need to panic. According to PLRA, record correction is <strong>free of cost</strong>, though the route depends on the type of mistake.</p>\n<h2>Four types of correction</h2>\n<table>\n<thead><tr><th>Type</th><th>When it applies</th></tr></thead>\n<tbody>\n<tr><td>Data entry correction</td><td>The computer record does not match the scanned manual record</td></tr>\n<tr><td>Manual record correction</td><td>There is a mistake in the old paper record from before computerization</td></tr>\n<tr><td>Mutation correction</td><td>There is a mistake in an approved mutation</td></tr>\n<tr><td>Name correction</td><td>There is a minor mistake in a name</td></tr>\n</tbody>\n</table>\n<h2>Where to apply and who approves</h2>\n<p>Apply at the relevant Arazi Record Centre or Dahi Markaz Mall, depending on the mistake. The ADLR or Land Record Officer approves corrections. <strong>NADRA biometric verification is mandatory</strong>. If you cannot go yourself, apply through a valid attested Mukhtarnama Aam.</p>\n<h2>Documents needed</h2>\n<ul>\n<li>CNIC (original and copy)</li>\n<li>Proof of ownership, such as a registry or mutation</li>\n<li>An affidavit explaining the mistake</li>\n<li>Supporting evidence, such as the manual record or copies</li>\n</ul>\n<h2>What is fard badar?</h2>\n<p>Fard badar is how mistakes in old paper records are corrected, prepared by the patwari or qanoongo. It covers <strong>only minor mistakes</strong> like spelling, measurement or typing errors that do not affect anyone\'s ownership. For computer records, a \"data entry fard badar\" is prepared, and it can be finished in 30 minutes if the documents are in order.</p>\n<h2>How to correct a name</h2>\n<p>Appear before the ADLR or Land Record Officer with:</p>\n<ul>\n<li>Two witnesses (a lumberdar and pattidar are preferred)</li>\n<li>An affidavit for name correction</li>\n<li>Proof of ownership (mutation or registry)</li>\n<li>CNIC and other identity documents</li>\n</ul>\n<p>This normally takes one working day after verification. Only minor corrections are allowed this way. <strong>A complete name change</strong> needs an order from a civil court, the District Collector or the Tehsildar. If the name is wrong in the registry, get the registry corrected at the Sub-Registrar office first.</p>\n<h2>When is a court order required?</h2>\n<ul>\n<li>When the mistake affects someone else\'s ownership or rights: an order of the District Collector or civil court.</li>\n<li>When long-standing entries are wrong: a civil court order.</li>\n</ul>\n<h2>Correcting an approved mutation</h2>\n<p>The revenue officer who approved a mutation can review it. Another officer can do so only with the District Collector\'s prior permission. This is possible until the mutation is part of the jamabandi. After that, the regular correction process through the District Collector applies.</p>\n<h2>If your request is rejected</h2>\n<p>Appeal to the Assistant Commissioner or District Collector, depending on the case. If a correction itself is wrong, send a written complaint to the PLRA Complaint Cell or go to the civil court.</p>\n<h2>More help</h2>\n<p>Open our <a href=\"https://www.assanzameen.com/tools/government-links\">Government Links Guide</a> to see all the official portals in one place. To contact PLRA or make a complaint, call <strong>(042) 111-22-22-77</strong> (Monday to Saturday, 8:00 AM to 5:00 PM).</p>\n<blockquote>This article was written on 1 November 2026 from information on the PLRA website. Assan Zameen is not a government body. Fees and procedures can change, so confirm with the relevant office before paying. This is not legal advice.</blockquote>',
  '<p>کبھی فرد نکلوانے پر پتا چلتا ہے کہ نام کے ہجے غلط ہیں یا رقبے کا اندراج مختلف ہے۔ گھبرانے کی ضرورت نہیں۔ PLRA کے مطابق ریکارڈ کی درستی کا عمل <strong>مفت</strong> ہے، البتہ غلطی کی نوعیت کے حساب سے راستہ بدل جاتا ہے۔</p>\n<h2>درستی کی چار اقسام</h2>\n<table>\n<thead><tr><th>قسم</th><th>کب ہوتی ہے؟</th></tr></thead>\n<tbody>\n<tr><td>ڈیٹا انٹری کی درستی</td><td>کمپیوٹر کا ریکارڈ اسکین شدہ پرانے ریکارڈ سے نہ ملے</td></tr>\n<tr><td>دستی ریکارڈ کی درستی</td><td>کمپیوٹرائزیشن سے پہلے کے کاغذی ریکارڈ میں غلطی ہو</td></tr>\n<tr><td>انتقال کی درستی</td><td>منظور شدہ انتقال میں غلطی ہو</td></tr>\n<tr><td>نام کی درستی</td><td>نام میں معمولی غلطی ہو</td></tr>\n</tbody>\n</table>\n<h2>درخواست کہاں دیں اور کون منظور کرے گا؟</h2>\n<p>غلطی کی نوعیت کے مطابق متعلقہ اراضی ریکارڈ سینٹر یا دیہی مرکز مال میں درخواست دیں۔ منظوری کا اختیار ADLR یا لینڈ ریکارڈ آفیسر کے پاس ہے۔ <strong>NADRA بائیو میٹرک تصدیق لازمی ہے</strong>، اور خود نہ جا سکیں تو تصدیق شدہ مختار نامہ عام کے ذریعے درخواست دی جا سکتی ہے۔</p>\n<h2>کون سے کاغذات چاہییں؟</h2>\n<ul>\n<li>شناختی کارڈ (اصل اور نقل)</li>\n<li>ملکیت کا ثبوت، جیسے رجسٹری یا انتقال</li>\n<li>غلطی کی وضاحت کے ساتھ بیانِ حلفی</li>\n<li>ثبوت، جیسے پرانا ریکارڈ یا نقول</li>\n</ul>\n<h2>فرد بدر کیا ہے؟</h2>\n<p>فرد بدر پرانے کاغذی ریکارڈ کی غلطی ٹھیک کرنے کا طریقہ ہے، جو پٹواری یا قانون گو تیار کرتا ہے۔ اس سے <strong>صرف معمولی غلطیاں</strong> ٹھیک ہوتی ہیں، جیسے ہجے، پیمائش یا ٹائپنگ کی غلطی، اور وہ بھی تب جب کسی کی ملکیت پر اثر نہ پڑے۔ کمپیوٹر والے ریکارڈ کی غلطی میں \"ڈیٹا انٹری فرد بدر\" بنتی ہے، جو کاغذات درست ہونے پر 30 منٹ میں بھی مکمل ہو سکتی ہے۔</p>\n<h2>نام ٹھیک کروانے کا طریقہ</h2>\n<p>ADLR یا لینڈ ریکارڈ آفیسر کے سامنے یہ چیزیں لے کر پیش ہوں:</p>\n<ul>\n<li>دو گواہ (نمبردار اور پتی دار کو ترجیح دی جاتی ہے)</li>\n<li>نام کی درستی کا بیانِ حلفی</li>\n<li>ملکیت کا ثبوت (انتقال یا رجسٹری)</li>\n<li>شناختی کارڈ اور دوسری شناختی دستاویزات</li>\n</ul>\n<p>تصدیق مکمل ہونے کے بعد عام طور پر یہ کام ایک کاروباری دن میں ہو جاتا ہے۔ یاد رہے کہ اس طریقے سے صرف معمولی درستی ہوتی ہے۔ <strong>نام پوری طرح بدلنے</strong> کے لیے سول عدالت، ڈسٹرکٹ کلکٹر یا تحصیلدار کا حکم چاہیے۔ اگر نام رجسٹری میں غلط ہے تو پہلے سب رجسٹرار آفس سے رجسٹری ٹھیک کروائیں۔</p>\n<h2>عدالتی حکم کب لازمی ہے؟</h2>\n<ul>\n<li>جب غلطی سے کسی دوسرے کی ملکیت یا حقوق متاثر ہوں: ڈسٹرکٹ کلکٹر یا سول عدالت کا حکم چاہیے۔</li>\n<li>جب پرانے اور طویل عرصے سے چلے آ رہے اندراجات غلط ہوں: سول عدالت کا حکم چاہیے۔</li>\n</ul>\n<h2>منظور شدہ انتقال کی درستی</h2>\n<p>جس ریونیو افسر نے انتقال منظور کیا، وہی اس پر نظرِ ثانی کر سکتا ہے۔ کوئی دوسرا افسر صرف ڈسٹرکٹ کلکٹر کی پیشگی اجازت سے ایسا کر سکتا ہے۔ یہ موقع تب تک ہے جب تک انتقال جمع بندی میں شامل نہ ہوا ہو۔ اس کے بعد ڈسٹرکٹ کلکٹر کے ذریعے باقاعدہ درستی کا عمل ہوگا۔</p>\n<h2>درخواست مسترد ہو جائے تو؟</h2>\n<p>معاملے کے مطابق اسسٹنٹ کمشنر یا ڈسٹرکٹ کلکٹر کے پاس اپیل کریں۔ اگر درستی ہی غلط ہو گئی ہو تو PLRA کے شکایت سیل کو تحریری شکایت دیں یا سول عدالت سے رجوع کریں۔</p>\n<h2>مزید مدد</h2>\n<p>تمام سرکاری پورٹلز کے لنکس ایک جگہ دیکھنے کے لیے ہماری <a href=\"https://www.assanzameen.com/tools/government-links?lang=ur\">سرکاری لنکس گائیڈ</a> کھولیں۔ PLRA سے شکایت یا رابطے کے لیے فون نمبر <strong>(042) 111-22-22-77</strong> ہے (پیر تا ہفتہ، صبح 8 سے شام 5 بجے تک)۔</p>\n<blockquote>یہ مضمون PLRA کی ویب سائٹ پر موجود معلومات کی بنیاد پر 1 نومبر 2026 کو لکھا گیا۔ آسان زمین سرکاری ادارہ نہیں ہے۔ فیس اور طریقہ کار بدل سکتے ہیں، اس لیے ادائیگی سے پہلے متعلقہ دفتر سے تصدیق کر لیں۔ یہ قانونی مشورہ نہیں ہے۔</blockquote>',
