-- 20. zameen-ki-taqseem-online-darkhwast-punjab
INSERT INTO `posts` (`id`, `user_id`, `title`, `title_ur`, `slug`, `category`, `featured_image`, `summary`, `summary_ur`, `content`, `content_ur`, `tags`, `read_time`, `views_count`, `likes_count`, `is_featured`, `status`, `created_at`, `updated_at`) VALUES (
  NULL,
  COALESCE((SELECT u.`id` FROM `users` u WHERE u.`role` = 'admin' ORDER BY u.`id` LIMIT 1), (SELECT MIN(u2.`id`) FROM `users` u2)),
  'Land Partition (Taqseem) in Punjab: How to Apply Online on PULSE',
  'مشترکہ زمین کی تقسیم کیسے کروائیں؟ پنجاب میں تقسیم کی آن لائن درخواست کا طریقہ',
  'zameen-ki-taqseem-online-darkhwast-punjab',
  'Property Guides',
  NULL,
  'How to separate your share of joint agricultural land: who can apply, the PULSE portal, the Tehsildar\'s role, time, fee and the right to appeal.',
  'مشترکہ زرعی زمین کا اپنا حصہ الگ کروانے کا طریقہ: درخواست کون دے سکتا ہے، PULSE پورٹل، تحصیلدار کا کردار، وقت، فیس اور اپیل کا حق۔',
  '<p>Much of Punjab\'s farmland is held in joint khewats. Your share exists on paper, but which piece on the ground is yours is not settled. This causes disputes and makes selling difficult. The solution is <strong>partition (taqseem)</strong>.</p>\n<h2>What does partition mean?</h2>\n<p>It separates the shares of co-owners so each gets an independent parcel in their own name. It is done under sections 135, 135-A and 147 of the Land Revenue Act, 1967.</p>\n<h2>Who can apply?</h2>\n<p>Any joint landholder whose name is in the khewat record. Overseas Pakistanis can apply online and authorize a local representative for field proceedings.</p>\n<h2>How to apply online</h2>\n<ol>\n<li>Open the <a href=\"https://askfortaqseem.pulse.gop.pk/\" rel=\"noopener\" target=\"_blank\">PULSE partition portal</a>.</li>\n<li>Select the district, tehsil and mouza.</li>\n<li>Enter the khewat number, name, CNIC and mobile number.</li>\n<li>Attach a copy of the <a href=\"https://www.assanzameen.com/blog/fard-kaise-hasil-karein-punjab-online-arc-guide\">fard</a> and submit.</li>\n<li>Keep the application number. You can track progress with it.</li>\n</ol>\n<h2>Applying manually</h2>\n<p>Submit a written application to your area\'s Tehsildar with copies of your CNIC and fard.</p>\n<h2>Fee and time</h2>\n<ul>\n<li><strong>Fee:</strong> according to PLRA, there is no fee for filing.</li>\n<li><strong>Time:</strong> usually 30 to 60 days, depending on verification and consent.</li>\n</ul>\n<h2>What happens after you apply?</h2>\n<p>The Tehsildar conducts the proceedings and ensures a fair division. If possession on the ground differs from the record, field staff record actual possession and adjust the division with consent. After verification, the Tehsildar or Revenue Officer issues a written order, which goes to the Arazi Record Centre to enter the new ownerships. New khewats are then updated.</p>\n<p>An owner normally receives one consolidated parcel unless this is physically impossible.</p>\n<h2>When partition cannot go ahead</h2>\n<p>If the land is mortgaged or under a court stay, partition is stopped until that is resolved. Check a fresh fard first.</p>\n<h2>If you disagree with the order</h2>\n<p>You can appeal to the District Collector within the legal time limit.</p>\n<h2>Work out your area</h2>\n<p>Use our <a href=\"https://www.assanzameen.com/tools/patwari-land-converter\">Land Unit Converter</a> to understand your area in kanal, marla, sarsahi and acre.</p>\n<h2>More help</h2>\n<p>Open our <a href=\"https://www.assanzameen.com/tools/government-links\">Government Links Guide</a> to see all the official portals in one place. To contact PLRA or make a complaint, call <strong>(042) 111-22-22-77</strong> (Monday to Saturday, 8:00 AM to 5:00 PM).</p>\n<blockquote>This article was written on 1 November 2026 from information on the PLRA website. Assan Zameen is not a government body. Fees and procedures can change, so confirm with the relevant office before paying. This is not legal advice.</blockquote>',
  '<p>پنجاب میں بہت سی زرعی زمین مشترکہ کھیوٹ میں ہوتی ہے۔ اس کا مطلب ہے کہ کاغذوں میں آپ کا حصہ تو ہے، مگر موقع پر کون سا ٹکڑا آپ کا ہے، یہ طے نہیں ہوتا۔ اسی وجہ سے جھگڑے اور فروخت میں مشکلات پیدا ہوتی ہیں۔ اس کا حل <strong>تقسیم</strong> ہے۔</p>\n<h2>تقسیم کا مطلب کیا ہے؟</h2>\n<p>شریک مالکان کے حصے الگ کرنا، تاکہ ہر ایک کو اپنے نام پر الگ ٹکڑا مل جائے۔ یہ کارروائی لینڈ ریونیو ایکٹ 1967 کی دفعات 135، 135-A اور 147 کے تحت ہوتی ہے۔</p>\n<h2>درخواست کون دے سکتا ہے؟</h2>\n<p>کوئی بھی مشترکہ مالک جس کا نام کھیوٹ کے ریکارڈ میں موجود ہو۔ بیرون ملک پاکستانی بھی آن لائن درخواست دے سکتے ہیں اور فیلڈ کی کارروائی کے لیے مقامی نمائندہ مقرر کر سکتے ہیں۔</p>\n<h2>آن لائن درخواست کا طریقہ</h2>\n<ol>\n<li><a href=\"https://askfortaqseem.pulse.gop.pk/\" rel=\"noopener\" target=\"_blank\">PULSE کا تقسیم پورٹل</a> کھولیں۔</li>\n<li>ضلع، تحصیل اور موضع منتخب کریں۔</li>\n<li>کھیوٹ نمبر، نام، شناختی کارڈ اور موبائل نمبر درج کریں۔</li>\n<li><a href=\"https://www.assanzameen.com/blog/fard-kaise-hasil-karein-punjab-online-arc-guide?lang=ur\">فرد</a> کی نقل لگا کر درخواست جمع کروائیں۔</li>\n<li>درخواست نمبر سنبھال لیں۔ اسی سے پورٹل پر پیش رفت دیکھی جا سکتی ہے۔</li>\n</ol>\n<h2>دستی درخواست</h2>\n<p>آن لائن نہ کر سکیں تو اپنے علاقے کے تحصیلدار کو شناختی کارڈ اور فرد کی نقول کے ساتھ تحریری درخواست دیں۔</p>\n<h2>فیس اور وقت</h2>\n<ul>\n<li><strong>فیس:</strong> PLRA کے مطابق درخواست پر کوئی فیس نہیں۔</li>\n<li><strong>وقت:</strong> عام طور پر 30 سے 60 دن، جو تصدیق اور شریک مالکان کی رضامندی پر منحصر ہے۔</li>\n</ul>\n<h2>درخواست کے بعد کیا ہوتا ہے؟</h2>\n<p>تحصیلدار کارروائی چلاتا ہے اور منصفانہ تقسیم یقینی بناتا ہے۔ اگر موقع کا قبضہ ریکارڈ سے مختلف ہو تو فیلڈ اسٹاف اصل قبضہ درج کرتا ہے اور رضامندی سے تقسیم کو اس کے مطابق کیا جاتا ہے۔ تصدیق کے بعد تحصیلدار یا ریونیو افسر تحریری حکم جاری کرتا ہے، جو نئی ملکیت کے اندراج کے لیے اراضی ریکارڈ سینٹر کو بھیجا جاتا ہے۔ اس کے بعد نئے کھیوٹ اور ملکیت اپ ڈیٹ ہو جاتی ہے۔</p>\n<p>عام طور پر ایک مالک کو ایک ہی یکجا ٹکڑا دیا جاتا ہے، سوائے اس کے کہ زمین کی وجہ سے ایسا ممکن نہ ہو۔</p>\n<h2>کن صورتوں میں تقسیم نہیں ہو سکتی؟</h2>\n<p>اگر زمین رہن ہو یا اس پر عدالتی حکمِ امتناعی ہو تو یہ مسئلہ حل ہونے تک تقسیم روک دی جاتی ہے۔ اس لیے پہلے تازہ فرد دیکھ لیں۔</p>\n<h2>فیصلہ پسند نہ آئے تو؟</h2>\n<p>قانونی مدت کے اندر ڈسٹرکٹ کلکٹر کے پاس اپیل کی جا سکتی ہے۔</p>\n<h2>رقبے کا حساب خود سمجھیں</h2>\n<p>تقسیم سے پہلے اپنا رقبہ سمجھنے کے لیے ہمارا <a href=\"https://www.assanzameen.com/tools/patwari-land-converter?lang=ur\">زمین یونٹ کنورٹر</a> استعمال کریں، جو کنال، مرلہ، سرساہی اور ایکڑ کا حساب کرتا ہے۔</p>\n<h2>مزید مدد</h2>\n<p>تمام سرکاری پورٹلز کے لنکس ایک جگہ دیکھنے کے لیے ہماری <a href=\"https://www.assanzameen.com/tools/government-links?lang=ur\">سرکاری لنکس گائیڈ</a> کھولیں۔ PLRA سے شکایت یا رابطے کے لیے فون نمبر <strong>(042) 111-22-22-77</strong> ہے (پیر تا ہفتہ، صبح 8 سے شام 5 بجے تک)۔</p>\n<blockquote>یہ مضمون PLRA کی ویب سائٹ پر موجود معلومات کی بنیاد پر 1 نومبر 2026 کو لکھا گیا۔ آسان زمین سرکاری ادارہ نہیں ہے۔ فیس اور طریقہ کار بدل سکتے ہیں، اس لیے ادائیگی سے پہلے متعلقہ دفتر سے تصدیق کر لیں۔ یہ قانونی مشورہ نہیں ہے۔</blockquote>',
  'زمین کی تقسیم,taqseem,land partition punjab,PULSE,تحصیلدار,مشترکہ کھیوٹ',
  '2',
